import {KEIGO_CATEGORIES,KEIGO_SCENES} from './keigo.mjs?v=keigo1';
const BASE_CATEGORIES = [{"id":"phone","name":"전화 응대","description":"전화 연결·회신·전달"},{"id":"reception","name":"방문·내방객","description":"방문 약속·안내·소개"},{"id":"schedule","name":"일정 조정","description":"회의 시간·기한·일정 변경"},{"id":"request","name":"정중한 요청","description":"부탁·위임·허락 구하기"},{"id":"confirm","name":"확인·되묻기","description":"복창·인식 맞추기·추가 질문"},{"id":"report","name":"보고·진행 상황","description":"결론 먼저·진척·문제 보고"},{"id":"meeting","name":"회의·발언","description":"진행·요약·발언 요청"},{"id":"disagree","name":"의견 차이","description":"반대·근거·합의점 찾기"},{"id":"decline","name":"거절·대안","description":"조건부 수락·대안 제시"},{"id":"apology","name":"사과·문제 대응","description":"실수 인정·원인·재발 방지"},{"id":"reminder","name":"독촉·기한 협의","description":"재촉·우선순위·기한 연장"},{"id":"email","name":"메일·문서","description":"첨부·수정본·참조·수신 확인"},{"id":"remote","name":"온라인·재택","description":"음성 문제·공유·비동기 협업"},{"id":"pricing","name":"견적·거래 조건","description":"가격·예산·범위·조건"},{"id":"delivery","name":"발주·납기","description":"수량·재고·분납·물류"},{"id":"handover","name":"인수인계·협업","description":"담당 변경·휴가·역할 분담"},{"id":"interview","name":"면접·취업","description":"질문·경험 설명·조건 확인"},{"id":"hotel","name":"호텔·접객","description":"예약·시설 안내·불편 대응"},{"id":"relations","name":"감사·배려","description":"감사·상대 배려·수고 인정"},{"id":"global","name":"해외 협업","description":"시차·승인·본사와 현지 조율"}];
const BASE_SCENES = [{"id":"biz-001","category":"phone","title":"부재중인 담당자에게 회신 요청","level":2,"setting":"거래처에 전화를 걸었지만 담당자가 자리에 없다.","dialogue":[{"speaker":"상대","voice":"female","text":"田中はただいま席を外しております。三時には戻る予定ですので、戻り次第、こちらからお電話いたしましょうか。"}],"meaning":"담당자가 3시에 돌아오면 먼저 전화해 줄 수 있다.","wrongMeanings":["담당자가 오늘은 회사에 돌아오지 않는다.","지금 바로 담당자에게 연결할 수 있다.","3시까지 다시 전화해 달라는 요청이다."],"goal":"제안을 받아들이고 연락처를 남기려면?","reply":"お願いいたします。電話番号をお伝えしてもよろしいでしょうか。","wrongReplies":[{"text":"では、三時に直接そちらへ伺います。","why":"전화 회신 대신 방문을 약속한다."},{"text":"こちらからの電話は不要です。","why":"자신의 전화를 하지 않겠다는 다른 내용이다."},{"text":"田中様に今すぐおつなぎください。","why":"담당자가 부재중이라는 정보를 무시한다."}],"explanation":"「戻り次第」는 돌아오는 즉시라는 뜻이다. 회신 제안을 수락한 뒤 연락처를 전하는 흐름이다.","formal":"お手数をおかけしますが、田中様から折り返しご連絡いただけますと幸いです。","internal":"戻ったら電話をもらえるよう、伝えてもらえますか。","pattern":"[担当者]から折り返しご連絡いただけますか。"},{"id":"biz-002","category":"phone","title":"다른 부서로 다시 연결받기","level":2,"setting":"고객지원 번호로 전화했지만 기술적인 문제는 다른 부서가 담당한다.","dialogue":[{"speaker":"상대","voice":"female","text":"操作方法につきましては、技術サポートが担当しております。そちらにおつなぎいたしますので、少々お待ちいただけますか。"}],"meaning":"기술지원 부서로 연결해 줄 테니 기다려 달라는 뜻이다.","wrongMeanings":["기술지원 번호로 직접 다시 걸라는 뜻이다.","기술지원이 이미 영업을 종료했다.","지금 부서가 사용 방법을 설명하겠다는 뜻이다."],"goal":"다른 부서로 연결해 주겠다는 제안에 응하려면?","reply":"承知いたしました。おつなぎいただけますか。","wrongReplies":[{"text":"それでは、修理の申し込みを取り消します。","why":"신청 취소는 대화에서 요구하지 않았다."},{"text":"操作方法は、こちらからご説明いたします。","why":"질문하는 사람과 설명하는 사람의 역할이 바뀐다."},{"text":"技術サポートには連絡しないでください。","why":"연결 제안을 거부하는 내용이다."}],"explanation":"「おつなぎいたします」는 상대를 다른 담당자에게 연결하겠다는 안내다.","formal":"恐れ入りますが、技術サポートのご担当者様におつなぎいただけますでしょうか。","internal":"技術サポートにつないでもらえますか。","pattern":"[部署]のご担当者様におつなぎいただけますか。"},{"id":"biz-003","category":"phone","title":"회사 이름을 정확하게 되묻기","level":3,"setting":"전화에서 거래처 회사 이름을 잘 듣지 못했다.","dialogue":[{"speaker":"상대","voice":"female","text":"青葉商事の森と申します。先日お送りした見積書の件で、営業部の佐藤様はいらっしゃいますか。"}],"meaning":"아오바상사의 모리 씨가 견적서 건으로 사토 씨를 찾고 있다.","wrongMeanings":["사토 씨가 아오바상사에 견적서를 요청한 통화다.","모리 씨가 자신의 사내 부서로 연결을 부탁한다.","모리 씨가 납품 수량 변경을 통보한다."],"goal":"회사 이름을 다시 확인하고 싶다면?","reply":"恐れ入りますが、御社名をもう一度お伺いしてもよろしいでしょうか。","wrongReplies":[{"text":"恐れ入りますが、弊社名を教えていただけますか。","why":"상대 회사인 御社와 자기 회사인 弊社가 뒤바뀐다."},{"text":"では、見積書の金額を変更いたします。","why":"금액 변경은 요청하지 않았다."},{"text":"佐藤は明日そちらに伺いました。","why":"시제와 전달 내용이 맞지 않으며 회사 이름을 확인하지 않는다."}],"explanation":"「御社」는 상대 회사, 「弊社」는 자신의 회사다. 듣지 못한 정보를 한정해 되묻는다.","formal":"恐れ入ります。念のため、御社名をもう一度お聞かせいただけますでしょうか。","internal":"すみません、会社名をもう一度お願いできますか。","pattern":"[確認したい情報]をもう一度お伺いしてもよろしいでしょうか。"},{"id":"biz-004","category":"phone","title":"담당자 부재와 회신 시각 전달","level":4,"setting":"동료가 외근 중이다. 거래처가 급한 문의로 전화를 했다.","dialogue":[{"speaker":"나","voice":"male","text":"鈴木さんと、本日中に確認したいことがあるのですが。"},{"speaker":"상대","voice":"female","text":"本日中に確認したいことがあるのですが、鈴木様は何時ごろお戻りになりますか。"}],"meaning":"상대는 오늘 안에 확인할 일이 있어 스즈키의 복귀 시각을 묻는다.","wrongMeanings":["내일까지 답변을 미뤄 달라는 뜻이다.","스즈키의 개인 연락처를 요구한다.","오늘 방문 예약을 취소하겠다는 뜻이다."],"goal":"스즈키가 16시에 복귀하며 이후 회신하게 하겠다고 안내하려면?","reply":"鈴木は十六時に戻る予定です。戻り次第、折り返しご連絡するよう申し伝えます。","wrongReplies":[{"text":"鈴木様は十六時にお戻りになられます。","why":"사외 상대에게 자기 회사 직원을 높이고 과도한 경어를 겹쳤다."},{"text":"鈴木は十六時までに必ずお電話いたしました。","why":"아직 하지 않은 전화를 과거에 완료했다고 한다."},{"text":"鈴木の予定は確認せず、明日またお電話ください。","why":"오늘 안에 확인하려는 상대의 필요를 충족하지 못한다."}],"explanation":"사외에 자기 회사 직원을 설명할 때는 「鈴木は戻る予定です」처럼 말한다. 모르는 연락 완료를 약속하지 않고 전달하겠다고 한다.","formal":"鈴木は十六時に帰社する予定でございます。戻り次第、ご連絡を差し上げるよう申し伝えます。","internal":"鈴木さんは十六時に戻る予定です。戻ったら折り返すよう伝えます。","pattern":"[自社の担当者]は[時刻]に戻る予定です。戻り次第、[対応]するよう申し伝えます。"},{"id":"biz-005","category":"reception","title":"예약이 없는 방문객 안내","level":2,"setting":"회사 접수 담당자로서 사전 약속 없이 온 방문객에게 응대한다.","dialogue":[{"speaker":"상대","voice":"female","text":"近くまで来ましたので、ご挨拶だけでもと思いまして。営業の山本様はいらっしゃいますか。"}],"meaning":"상대는 근처에 왔다가 사전 약속 없이 인사하려고 방문했다.","wrongMeanings":["상대는 이미 면담 시간을 확정했다.","상대는 우편물을 수령하러 왔다.","상대는 면담을 취소하려 한다."],"goal":"담당자의 면담 가능 여부를 먼저 확인하려면?","reply":"確認いたしますので、こちらで少々お待ちいただけますか。","wrongReplies":[{"text":"山本は必ずお会いしますので、すぐにお入りください。","why":"확인 없이 면담을 확약하고 입장을 허용한다."},{"text":"本日の面談はキャンセルとのことで承りました。","why":"방문을 면담 취소로 잘못 이해한다."},{"text":"山本様にお伺いしてください。","why":"방문객의 행동에 자기 쪽의 겸양어 伺う를 쓰면 맞지 않는다."}],"explanation":"확인되지 않은 면담을 약속하지 않고 담당자의 사정을 먼저 확인한다.","formal":"担当者の都合を確認してまいりますので、恐れ入りますが、こちらでお待ちいただけますでしょうか。","internal":"会えるか確認しますので、少しお待ちください。","pattern":"[担当者の都合]を確認いたしますので、少々お待ちいただけますか。"},{"id":"biz-006","category":"reception","title":"회의실로 안내받기","level":2,"setting":"약속 시각에 거래처 사무실에 도착했다.","dialogue":[{"speaker":"상대","voice":"female","text":"お待ちしておりました。会議室へご案内いたします。お荷物はこちらでお預かりいたしましょうか。"}],"meaning":"회의실로 안내하면서 짐을 맡아 주겠다고 제안한다.","wrongMeanings":["회의실 사용이 불가능하다는 뜻이다.","짐을 회의실에 두고 나가라는 뜻이다.","짐을 직접 배송해 달라는 뜻이다."],"goal":"짐을 맡기는 제안에 감사하며 수락하려면?","reply":"ありがとうございます。それでは、こちらの荷物をお願いいたします。","wrongReplies":[{"text":"それでは、会議室の予約を取り消します。","why":"회의실 예약을 취소하는 내용이다."},{"text":"こちらからお荷物を発送いたします。","why":"짐 보관이 아니라 배송을 제안한다."},{"text":"お荷物を持ってお帰りください。","why":"안내받는 사람이 상대에게 귀가하라고 한다."}],"explanation":"「お預かりする」는 잠시 맡아 보관한다는 뜻이다. 「荷物をお願いします」로 맡길 물건을 분명히 한다.","formal":"お心遣いありがとうございます。恐れ入りますが、こちらの荷物をお預かりいただけますでしょうか。","internal":"ありがとうございます。この荷物を預かってもらえますか。","pattern":"[配慮へのお礼]。それでは、[お願いする内容]をお願いいたします。"},{"id":"biz-007","category":"reception","title":"사외 방문에서 자기 상사 소개","level":3,"setting":"거래처 앞에서 함께 온 자신의 부장을 소개한다.","dialogue":[{"speaker":"상대","voice":"female","text":"本日は、営業部の責任者の方もご一緒にお越しいただけると伺っております。"}],"meaning":"오늘 영업부 책임자도 함께 방문한다고 들었다는 뜻이다.","wrongMeanings":["거래처가 자기 회사 책임자를 부르겠다는 뜻이다.","상대가 책임자 없는 방문을 요구한다.","책임자의 방문 일정이 취소됐다는 뜻이다."],"goal":"자기 회사 영업부장 사토를 소개하려면?","reply":"こちらが弊社の営業部長の佐藤でございます。","wrongReplies":[{"text":"こちらが佐藤部長様でいらっしゃいます。","why":"사외에서 자기 회사 상사를 높이는 소개다."},{"text":"こちらが御社の営業部長の佐藤でございます。","why":"자기 회사 사람을 상대 회사 사람이라고 소개한다."},{"text":"佐藤様にご紹介していただきます。","why":"지금 책임자를 소개하는 답변이 아니다."}],"explanation":"사외에서는 상사도 자기 회사 구성원으로 소개한다. 「弊社の営業部長の佐藤」가 관계를 명확하게 한다.","formal":"弊社で営業部門を担当しております、佐藤でございます。","internal":"こちらが営業部長の佐藤です。","pattern":"こちらが弊社の[役職]の[氏名]でございます。"},{"id":"biz-008","category":"reception","title":"보안 절차 안내","level":4,"setting":"회사 방문객은 출입증을 받고 사진 촬영을 삼가야 한다.","dialogue":[{"speaker":"나","voice":"male","text":"入館するときに、必要な手続きを教えていただけますか。"},{"speaker":"상대","voice":"female","text":"受付で入館証をお受け取りください。執務エリアでは、情報管理の都合上、撮影をご遠慮いただいております。"}],"meaning":"출입증을 수령해야 하며 사무 구역에서는 촬영이 제한된다.","wrongMeanings":["출입증 없이도 사무 구역에 들어갈 수 있다.","회의실 안에서는 반드시 사진을 찍어야 한다.","정보 관리 때문에 오늘 모든 방문이 취소됐다."],"goal":"안내를 이해하고 따르겠다고 답하려면?","reply":"承知いたしました。入館証を受け取り、撮影は控えます。","wrongReplies":[{"text":"入館証は受け取らず、先に執務エリアへ参ります。","why":"출입 절차를 건너뛴다."},{"text":"撮影した画像は、社外に公開いたします。","why":"촬영 제한과 정보 관리 목적에 어긋난다."},{"text":"本日の訪問は中止ということでよろしいですね。","why":"촬영 제한을 방문 취소로 잘못 이해한다."}],"explanation":"「ご遠慮いただいております」는 단순 취향이 아니라 이 상황에서 지켜야 하는 제한 안내다.","formal":"ご案内ありがとうございます。入館手続きを済ませ、撮影は差し控えます。","internal":"わかりました。入館証を受け取って、撮影は控えます。","pattern":"承知いたしました。[必要な手続き]を済ませ、[控える行為]は控えます。"},{"id":"biz-009","category":"schedule","title":"두 후보 중 회의 시간 선택","level":2,"setting":"거래처가 다음 주 회의 시간을 제안한다.","dialogue":[{"speaker":"상대","voice":"female","text":"来週の火曜日でしたら、午前十時か午後三時であれば調整可能です。どちらがよろしいでしょうか。"}],"meaning":"다음 주 화요일 10시와 15시 중 선택할 수 있다.","wrongMeanings":["다음 주 화요일은 하루 종일 불가능하다.","10시부터 15시까지 연속 회의하자는 뜻이다.","화요일이 아닌 수요일을 제안한다."],"goal":"오후 3시로 정하고 싶다면?","reply":"それでは、火曜日の午後三時でお願いいたします。","wrongReplies":[{"text":"火曜日の午前九時で確定させていただきます。","why":"제시하지 않은 시간을 확정한다."},{"text":"火曜日は終日お時間をいただきます。","why":"종일 시간을 쓰는 제안으로 바뀐다."},{"text":"水曜日の午後三時に伺いました。","why":"요일과 시제가 맞지 않는다."}],"explanation":"「十時か三時」는 두 후보 중 하나다. 선택한 요일과 시각을 함께 복창한다.","formal":"それでは、来週火曜日の十五時にお時間を頂戴できますでしょうか。","internal":"火曜の十五時でお願いします。","pattern":"それでは、[曜日]の[時刻]でお願いいたします。"},{"id":"biz-010","category":"schedule","title":"회의 시작을 늦춰 달라는 요청","level":3,"setting":"당일 앞선 회의가 길어져 약속 시각에 참석하기 어렵다.","dialogue":[{"speaker":"상대","voice":"female","text":"先ほどの打ち合わせが長引いておりまして、開始を十五分遅らせていただくことは可能でしょうか。"}],"meaning":"앞선 회의가 길어져 시작을 15분 늦출 수 있는지 묻는다.","wrongMeanings":["회의를 15분 일찍 시작해 달라는 뜻이다.","회의 시간을 15분으로 줄여 달라는 뜻이다.","오늘 회의를 완전히 취소하겠다는 뜻이다."],"goal":"15분 늦추는 것이 가능하다고 답하려면?","reply":"承知いたしました。それでは、開始を十五分後ろにずらしましょう。","wrongReplies":[{"text":"では、予定より十五分早く始めましょう。","why":"변경 방향이 반대다."},{"text":"本日の会議は中止といたします。","why":"연기가 아니라 취소로 처리한다."},{"text":"会議の内容は十五分前に送付済みです。","why":"시작 시각 변경에 답하지 않는다."}],"explanation":"「遅らせる」「後ろにずらす」는 시작을 늦추는 표현이다. 「前倒し」는 반대 방향이다.","formal":"かしこまりました。開始時刻を十五分遅らせる形で調整いたします。","internal":"大丈夫です。十五分後ろにずらしましょう。","pattern":"[開始時刻]を[時間]後ろにずらす形で調整いたします。"},{"id":"biz-011","category":"schedule","title":"확정과 임시 확보 구분","level":4,"setting":"상대가 회의실을 아직 최종 확정하지 않았다.","dialogue":[{"speaker":"상대","voice":"female","text":"会議室は仮押さえしておりますが、参加人数が確定してから正式に予約する予定です。"}],"meaning":"회의실은 임시 확보 상태이며 인원 확정 후 정식 예약한다.","wrongMeanings":["회의실 예약이 이미 완전히 확정됐다.","인원과 관계없이 회의실을 취소할 예정이다.","참가 인원은 회의 당일에만 확인할 수 있다."],"goal":"아직 확정 전이라는 이해를 확인하려면?","reply":"現時点では仮予約で、人数確定後に正式予約されるという理解でよろしいでしょうか。","wrongReplies":[{"text":"正式予約が完了したとのことで、全員に確定の案内を出します。","why":"임시 확보를 최종 확정으로 잘못 이해한다."},{"text":"人数が決まっても、予約はしないということですね。","why":"정식 예약할 예정이라는 내용을 반대로 이해한다."},{"text":"会議室が取れないため、中止ということですね。","why":"공간 확보가 불가능하다고 말한 것이 아니다."}],"explanation":"「仮押さえ」는 최종 확정을 뜻하지 않는다. 임시·확정 상태를 구분해 확인한다.","formal":"念のための確認ですが、人数が確定した段階で正式予約となるとの認識で相違ございませんでしょうか。","internal":"今は仮押さえで、人数が決まってから正式予約ということですね。","pattern":"現時点では[仮の状態]で、[条件]の後に[確定の手続き]という理解でよろしいでしょうか。"},{"id":"biz-012","category":"schedule","title":"복합 일정 조건 조율","level":5,"setting":"두 팀의 회의 가능한 시간이 다르다.","dialogue":[{"speaker":"나","voice":"male","text":"打ち合わせの時間について、ご都合を教えていただけますか。"},{"speaker":"상대","voice":"female","text":"午前中は難しいのですが、十四時以降であれば参加できます。なお、十六時から別件が入っておりますので、一時間以内ですと助かります。"}],"meaning":"14시 이후 시작해 16시 전 끝나는 1시간 이내 회의를 원한다.","wrongMeanings":["오전 중 1시간 회의만 가능하다.","16시 이후 시작하는 회의를 원한다.","14시부터 16시까지 2시간 회의를 요청한다."],"goal":"조건을 충족하는 14시 30분~15시 30분을 제안하려면?","reply":"それでは、十四時半から十五時半までの一時間ではいかがでしょうか。","wrongReplies":[{"text":"十六時から十八時まででお願いいたします。","why":"다른 일정과 겹치고 길이도 넘는다."},{"text":"午前十時から十一時でいかがでしょうか。","why":"오전에는 어렵다는 조건에 맞지 않는다."},{"text":"十四時から十六時までの二時間にしましょう。","why":"1시간 이내라는 요청을 충족하지 못한다."}],"explanation":"시작 가능 시각·다음 일정·희망 길이를 함께 들어야 한다. 세 조건을 모두 충족하는 시간을 제안한다.","formal":"ご都合を踏まえ、十四時三十分から十五時三十分で設定させていただいてもよろしいでしょうか。","internal":"十四時半から一時間でどうですか。","pattern":"[開始時刻]から[終了時刻]までの[所要時間]ではいかがでしょうか。"},{"id":"biz-013","category":"request","title":"자료 확인을 정중하게 부탁","level":2,"setting":"선배에게 회의 자료 검토를 부탁하려 한다.","dialogue":[{"speaker":"상대","voice":"female","text":"会議まで、まだ少し時間があります。確認してほしい箇所があれば、先に送っておいてください。"}],"meaning":"검토받고 싶은 부분이 있다면 회의 전에 보내 달라는 뜻이다.","wrongMeanings":["회의 후에만 자료를 보겠다는 뜻이다.","이미 모든 검토가 끝났다는 뜻이다.","자료를 보내지 말라는 뜻이다."],"goal":"자료의 수치 부분 검토를 부탁하려면?","reply":"ありがとうございます。資料の数値の部分をご確認いただけますか。","wrongReplies":[{"text":"ありがとうございます。数値の確認は不要ということですね。","why":"검토 제안을 검토 불필요로 잘못 이해한다."},{"text":"資料は会議終了後までお送りしません。","why":"미리 보내 달라는 요청과 맞지 않는다."},{"text":"資料をご確認して差し上げます。","why":"검토를 부탁하는 상황에서 행위 주체가 바뀐다."}],"explanation":"검토해 주겠다는 제안에 감사한 뒤 필요한 범위를 특정하면 상대의 부담을 줄일 수 있다.","formal":"恐れ入りますが、特に数値の整合性をご確認いただけますと幸いです。","internal":"ありがとうございます。数字の部分を見てもらえますか。","pattern":"特に[確認してほしい範囲]をご確認いただけますか。"},{"id":"biz-014","category":"request","title":"불필요한 작업 줄여 부탁","level":3,"setting":"급한 자료 요청이지만 상대에게 새 파일을 만들게 하고 싶지는 않다.","dialogue":[{"speaker":"상대","voice":"female","text":"現在の在庫状況は確認できますが、一覧表を新しく作成するとなると、少しお時間をいただきます。"}],"meaning":"재고는 확인할 수 있지만 새 목록표를 만들려면 시간이 더 필요하다.","wrongMeanings":["재고 확인 자체가 불가능하다.","새 목록표가 이미 완성됐다.","재고를 내일 모두 입고한다는 뜻이다."],"goal":"기존 자료만으로 괜찮다고 전하려면?","reply":"既存の資料で結構ですので、在庫がわかるものをお送りいただけますか。","wrongReplies":[{"text":"必ず新しい一覧表を今すぐ作成してください。","why":"새 파일을 만들게 하지 않겠다는 목적에 맞지 않는다."},{"text":"では、在庫の確認も不要です。","why":"확인 자체를 포기하는 다른 내용이다."},{"text":"一覧表の完成まで、出荷をすべて止めてください。","why":"요청하지 않은 출하 중단을 지시한다."}],"explanation":"「既存の資料で結構です」는 원하는 정보는 받되 새 문서 작성 부담은 덜겠다는 뜻이다.","formal":"新たにご作成いただく必要はございませんので、在庫を確認できる既存資料をご共有いただけますでしょうか。","internal":"今ある資料で大丈夫なので、在庫がわかるものを送ってもらえますか。","pattern":"新たに[作業]いただく必要はありませんので、既存の[資料]をご共有いただけますか。"},{"id":"biz-015","category":"request","title":"담당 범위 한정해 협조 요청","level":4,"setting":"다른 부서에 전체 자료가 아닌 담당 부분 검토만 부탁한다.","dialogue":[{"speaker":"상대","voice":"female","text":"全体を確認するとなると今週は難しいですが、販売実績の部分であれば確認できます。"}],"meaning":"전체 검토는 어렵지만 판매 실적 부분은 검토할 수 있다.","wrongMeanings":["판매 실적도 검토할 수 없다는 뜻이다.","전체 자료를 이번 주에 검토하겠다는 뜻이다.","판매 실적을 삭제해 달라는 뜻이다."],"goal":"상대가 제시한 범위로 부탁하려면?","reply":"それでは、販売実績の部分に絞って、ご確認をお願いいたします。","wrongReplies":[{"text":"では、全ページを今週中にご確認ください。","why":"전체 검토가 어렵다는 조건을 무시한다."},{"text":"販売実績の部分は確認しないでください。","why":"가능하다고 한 검토를 막는다."},{"text":"販売実績はすべて削除しておきます。","why":"검토 요청을 삭제 작업으로 바꾼다."}],"explanation":"「部分に絞って」는 범위를 제한하는 표현이다. 상대가 제시한 협조 가능 범위를 존중한다.","formal":"ご対応可能な販売実績の箇所のみ、ご確認をお願いできますでしょうか。","internal":"では、販売実績のところだけ確認をお願いします。","pattern":"[対応可能な範囲]に絞って、ご確認をお願いいたします。"},{"id":"biz-016","category":"request","title":"상사 승인 전 외부 전달 보류","level":5,"setting":"사외에 자료를 공유하려 하지만 아직 내부 승인이 끝나지 않았다.","dialogue":[{"speaker":"나","voice":"male","text":"資料は、先方に今日中に送る予定ですか。"},{"speaker":"상대","voice":"female","text":"先方には今日中に送ってほしいと言われていますが、部長の確認がまだ済んでいません。確認前に送るのは避けたいと思っています。"}],"meaning":"오늘 발송 요청이 있지만 부장 확인 전에는 보내지 않으려 한다.","wrongMeanings":["부장 확인이 끝났으므로 즉시 보내면 된다.","사외에서 자료를 받지 않겠다고 했다.","부장에게 확인하지 않고 보내라는 지시다."],"goal":"선배에게 부장 확인을 우선 진행하도록 협조를 요청하려면?","reply":"先方への送付前に、部長の確認を優先して進めていただけますか。","wrongReplies":[{"text":"確認は後回しにして、先に送ってください。","why":"확인 전에 발송하지 않으려는 목적과 반대다."},{"text":"先方には、すでに送付したと伝えてください。","why":"실제 상태와 다른 내용을 전달하게 한다."},{"text":"部長への確認は、今後一切不要とします。","why":"이번 요청 범위를 넘어 승인 절차를 없앤다."}],"explanation":"급한 외부 요청과 내부 확인 절차를 모두 듣고, 발송 전 확인을 우선할 수 있도록 요청한다.","formal":"恐れ入りますが、先方への送付に先立ち、部長の確認を優先してお取り次ぎいただけますでしょうか。","internal":"送る前に、部長の確認を先に進めてもらえますか。","pattern":"[外部への対応]に先立ち、[必要な確認]を優先して進めていただけますか。"},{"id":"biz-017","category":"confirm","title":"날짜와 시각을 복창하기","level":2,"setting":"전화로 제출 시각을 확인한다.","dialogue":[{"speaker":"상대","voice":"female","text":"修正版は、来週の水曜日、正午までにお送りいただけますか。"}],"meaning":"수정본을 다음 주 수요일 정오까지 보내 달라는 요청이다.","wrongMeanings":["이번 주 수요일 자정까지 보내 달라는 요청이다.","다음 주 금요일 오후에 보내 달라는 요청이다.","수정본을 보내지 말라는 요청이다."],"goal":"기한을 정확하게 복창하려면?","reply":"来週水曜日の正午までですね。承知いたしました。","wrongReplies":[{"text":"今週水曜日の午前零時までですね。","why":"주차와 시각이 다르다."},{"text":"来週金曜日までにお待ちしております。","why":"요일과 보내는 주체가 달라졌다."},{"text":"修正版は送らないようにいたします。","why":"발송 요청과 반대다."}],"explanation":"「正午」는 낮 12시다. 접수한 기한을 그대로 반복해 오해를 줄인다.","formal":"来週水曜日の十二時までにお送りする、ということで承知いたしました。","internal":"来週の水曜、お昼十二時までですね。","pattern":"[日付]の[時刻]までですね。承知いたしました。"},{"id":"biz-018","category":"confirm","title":"들리지 않은 부분만 되묻기","level":3,"setting":"온라인 회의에서 마지막 설명을 놓쳤다.","dialogue":[{"speaker":"상대","voice":"female","text":"納品日は変更ありませんが、受け取り場所だけ、第一倉庫ではなく第二倉庫に変更となります。"}],"meaning":"납품일은 같고 수령 장소만 제2창고로 바뀐다.","wrongMeanings":["납품일만 바뀌고 장소는 같다.","제1창고와 제2창고에 모두 납품해야 한다.","모든 납품이 취소됐다."],"goal":"장소가 제2창고가 맞는지 확인하려면?","reply":"恐れ入ります。受け取り場所は第二倉庫に変更、ということでよろしいでしょうか。","wrongReplies":[{"text":"納品日は明日に変更、ということですね。","why":"변경되지 않은 날짜를 임의로 바꾼다."},{"text":"第一倉庫への納品を継続いたします。","why":"바뀐 장소를 반영하지 않는다."},{"text":"両方の倉庫に納品いたします。","why":"양쪽 납품을 요구한 적이 없다."}],"explanation":"「だけ」「ではなく」를 들으면 바뀌는 항목과 유지되는 항목을 구분한다.","formal":"念のため、変更後のお受け取り場所は第二倉庫との理解で相違ございませんでしょうか。","internal":"受け取りは第二倉庫に変わった、ということですね。","pattern":"[変更項目]は[変更後の内容]、ということでよろしいでしょうか。"},{"id":"biz-019","category":"confirm","title":"애매한 표현을 구체화","level":4,"setting":"상사가 자료를 가능한 한 빨리 달라고 한다.","dialogue":[{"speaker":"상대","voice":"female","text":"できるだけ早めにお願いしたいのですが、ほかの業務との兼ね合いもあると思いますので、目安を教えてください。"}],"meaning":"가능한 한 빨리 처리하되 현실적인 완료 예상 시점을 알려 달라는 뜻이다.","wrongMeanings":["다른 업무를 전부 중단하라는 뜻이다.","완료 예상 시점을 말하지 말라는 뜻이다.","이미 기한을 오늘 12시로 확정했다는 뜻이다."],"goal":"내일 오전 완료가 가능하다고 확인받으려면?","reply":"明日の午前中でしたら対応可能ですが、その予定で進めてもよろしいでしょうか。","wrongReplies":[{"text":"目安はお伝えせずに進めます。","why":"예상 시점을 알려 달라는 요청을 따르지 않는다."},{"text":"ほかの業務はすべて中止すると決定しました。","why":"상대가 지시하지 않은 중단을 임의로 결정한다."},{"text":"本日の正午までに完了したということですね。","why":"언급하지 않은 시점과 완료 상태를 확정한다."}],"explanation":"막연한 「早めに」를 자신의 업무와 조율해 구체적인 시점으로 바꿔 확인한다.","formal":"恐れ入りますが、明日の午前中の完了を目途に進めさせていただいてもよろしいでしょうか。","internal":"明日の午前中ならできますが、それで大丈夫ですか。","pattern":"[対応可能な時期]でしたら対応可能ですが、その予定でよろしいでしょうか。"},{"id":"biz-020","category":"confirm","title":"결정 사항과 검토 사항 구분","level":5,"setting":"회의에서 결정된 것만 기록해야 한다.","dialogue":[{"speaker":"나","voice":"male","text":"導入するかどうかは、本日決まったと考えてよろしいですか。"},{"speaker":"상대","voice":"female","text":"今回は導入するかどうかを決めたわけではありません。まず試用して、結果を見てから、来月あらためて判断しましょう。"}],"meaning":"도입은 미확정이며 시험 사용 결과를 보고 다음 달 판단한다.","wrongMeanings":["이번 회의에서 정식 도입을 확정했다.","시험 사용 없이 다음 달 도입한다.","이번 달 안에 모든 사용을 중단한다."],"goal":"회의록에 남길 결론을 확인하려면?","reply":"現時点では試用のみを進め、導入の可否は来月判断する、という整理でよろしいでしょうか。","wrongReplies":[{"text":"本日、正式導入を決定したと記載します。","why":"도입 미확정이라는 발언과 반대다."},{"text":"試用は行わず、すべて見送ると記載します。","why":"우선 시험 사용한다는 결정을 누락한다."},{"text":"判断の時期は今月末で確定ですね。","why":"다음 달이라는 시점을 바꾼다."}],"explanation":"「決めたわけではない」는 확정하지 않았다는 뜻이다. 시험 사용과 최종 도입 결정을 나누어 요약한다.","formal":"試用を先行し、正式導入については来月あらためて審議する、との認識で相違ございませんでしょうか。","internal":"まず試して、導入するかは来月決める、ということですね。","pattern":"現時点では[先行する行動]を進め、[最終決定]は[時期]に判断するという整理でよろしいでしょうか。"},{"id":"biz-021","category":"report","title":"완료 보고와 다음 조치","level":2,"setting":"상사가 자료 발송 여부를 묻는다.","dialogue":[{"speaker":"상대","voice":"female","text":"例の資料は、もう先方に送りましたか。送付後は、受け取りの確認もお願いします。"}],"meaning":"자료 발송뿐 아니라 상대의 수신 확인도 요청한다.","wrongMeanings":["자료를 보내지 말라는 뜻이다.","발송만 하면 후속 확인은 필요 없다는 뜻이다.","자료 내용을 모두 다시 쓰라는 뜻이다."],"goal":"발송은 완료했고 수신 확인은 진행 중이라고 보고하려면?","reply":"資料の送付は完了しました。現在、先方の受け取りを確認しております。","wrongReplies":[{"text":"送付は完了しましたので、確認は一切いたしません。","why":"추가로 요청한 수신 확인을 거부한다."},{"text":"資料はまだ送っていませんが、送付済みと報告します。","why":"실제 상태와 다른 보고다."},{"text":"資料は全ページ削除いたしました。","why":"요청과 관계없는 삭제를 보고한다."}],"explanation":"완료한 일과 진행 중인 일을 분리해 말하면 상태가 분명해진다.","formal":"資料は送付済みでございます。受領状況について、引き続き確認しております。","internal":"資料は送りました。届いているか確認中です。","pattern":"[完了した作業]は完了しました。現在、[次の作業]を進めております。"},{"id":"biz-022","category":"report","title":"지연 가능성 조기 보고","level":3,"setting":"시험 결과가 늦어져 일정에 영향이 있을 수 있다.","dialogue":[{"speaker":"상대","voice":"female","text":"試験結果がまだ出ていないため、予定どおりに資料をまとめられない可能性があります。"}],"meaning":"시험 결과가 아직 없어 자료 정리가 예정대로 되지 않을 수도 있다.","wrongMeanings":["자료가 이미 완성됐다는 뜻이다.","시험 결과가 불합격으로 확정됐다는 뜻이다.","일정에 영향이 전혀 없다는 뜻이다."],"goal":"지연 가능성과 다음 보고 시점을 함께 전하려면?","reply":"結果待ちのため、資料作成が遅れる可能性があります。本日十六時に、あらためて状況をご報告します。","wrongReplies":[{"text":"予定どおり完了したと報告しておきます。","why":"아직 완료하지 않은 일을 완료로 보고한다."},{"text":"試験は不合格と確定しました。","why":"결과 미확정을 불합격 확정으로 바꾼다."},{"text":"状況がわかっても、ご報告は控えます。","why":"후속 보고를 하지 않겠다는 내용이다."}],"explanation":"가능성과 확정 사실을 구분한다. 아직 모르는 결과를 단정하지 않고 다음 업데이트 시각을 제시한다.","formal":"現時点では遅延の可能性がございます。十六時を目途に最新状況をご報告いたします。","internal":"結果待ちで遅れるかもしれません。十六時にもう一度報告します。","pattern":"[理由]のため、[影響]の可能性があります。[時刻]にあらためてご報告します。"},{"id":"biz-023","category":"report","title":"불리한 사실도 결론부터 보고","level":4,"setting":"검수에서 잘못된 수량을 발견했다.","dialogue":[{"speaker":"상대","voice":"female","text":"注文書では五十個ですが、到着したのは四十八個でした。まず不足分を確認し、担当者に連絡してください。"}],"meaning":"주문 50개 중 48개만 도착했으므로 부족 수량을 확인해 담당자에게 연락해야 한다.","wrongMeanings":["주문보다 2개 더 도착했다.","48개 주문해 50개 받았다.","수량이 일치해 연락이 필요 없다."],"goal":"부족 수량을 결론부터 보고하려면?","reply":"二個不足しております。注文書と現物を再確認したうえで、担当者に連絡いたします。","wrongReplies":[{"text":"二個余っておりますので、返送します。","why":"부족과 초과를 반대로 이해한다."},{"text":"数量は一致していました。連絡は不要です。","why":"실제 수량 차이를 무시한다."},{"text":"五十個すべて廃棄いたします。","why":"요청하지 않은 처분을 결정한다."}],"explanation":"50−48=2개 부족이다. 수량 차이와 확인·연락의 순서를 함께 말한다.","formal":"注文数量に対し二個の不足がございます。再照合のうえ、担当者へ確認いたします。","internal":"二個足りません。もう一度数を確認してから連絡します。","pattern":"[数量]不足しております。[確認]したうえで、[相手]に連絡いたします。"},{"id":"biz-024","category":"report","title":"잠정 수치와 확정 수치 구분","level":5,"setting":"집계가 아직 완료되지 않은 실적을 공유한다.","dialogue":[{"speaker":"나","voice":"male","text":"今月の実績について、集計の状況を教えてください。"},{"speaker":"상대","voice":"female","text":"現時点の集計では、前月を上回っています。ただ、一部店舗のデータが未反映ですので、確定値は明日お知らせします。"}],"meaning":"현재 잠정 집계는 전월보다 높지만 일부 데이터가 빠져 확정치는 내일 나온다.","wrongMeanings":["모든 데이터가 반영된 최종 실적이다.","전월보다 낮다는 결론이 확정됐다.","내일도 데이터 공개가 전혀 불가능하다."],"goal":"상사에게 오해 없이 요약하려면?","reply":"暫定集計では前月を上回っていますが、未反映のデータがあるため、確定値は明日ご報告します。","wrongReplies":[{"text":"全店舗の集計が完了し、最終値が確定しました。","why":"미반영 데이터가 있다는 점을 누락한다."},{"text":"前月割れが確定したとお伝えします。","why":"증가 방향과 확정 여부가 모두 다르다."},{"text":"明日の報告は不要ということですね。","why":"확정치를 내일 알린다는 내용과 반대다."}],"explanation":"「現時点」「未反映」「確定値」는 숫자의 확정 정도를 나타내는 단서다.","formal":"一部データ未反映の暫定値である点を添え、確定結果は明日ご報告いたします。","internal":"今の集計では前月より上ですが、未反映分があるので確定は明日です。","pattern":"[暫定の結果]ですが、[未確定の理由]のため、確定値は[時期]にご報告します。"},{"id":"biz-025","category":"meeting","title":"발언 기회 요청","level":2,"setting":"진행자가 회의 참석자에게 질문을 받는다.","dialogue":[{"speaker":"상대","voice":"female","text":"ここまでで、ご質問や補足したいことがあればお願いいたします。"}],"meaning":"지금까지 내용에 대해 질문이나 보충 설명을 요청한다.","wrongMeanings":["회의를 즉시 끝내고 퇴실하라는 뜻이다.","추가 의견은 받지 않겠다는 뜻이다.","결정을 이미 취소했다는 뜻이다."],"goal":"한 가지 질문을 하려고 발언하려면?","reply":"一点、質問してもよろしいでしょうか。","wrongReplies":[{"text":"ご質問は受け付けておりません。","why":"진행자에게 말할 자신의 질문을 막는 내용이다."},{"text":"それでは、会議は終了させていただきます。","why":"참석자가 질문 대신 회의를 종료한다."},{"text":"資料はすべて削除しておきました。","why":"발언 기회를 요청하는 답변이 아니다."}],"explanation":"짧게 발언 허락을 구한 다음 질문을 이어 갈 수 있다.","formal":"恐れ入りますが、一点確認させていただいてもよろしいでしょうか。","internal":"一つ、質問してもいいですか。","pattern":"一点、[質問／補足]してもよろしいでしょうか。"},{"id":"biz-026","category":"meeting","title":"논의 범위 되돌리기","level":3,"setting":"회의가 본래 의제에서 벗어나고 있다.","dialogue":[{"speaker":"상대","voice":"female","text":"その点も大切ですが、今日はまず来月の販売計画を決めたいと思います。"}],"meaning":"다른 쟁점도 중요하지만 오늘은 다음 달 판매 계획을 먼저 결정하려 한다.","wrongMeanings":["모든 추가 쟁점을 오늘 끝내겠다는 뜻이다.","판매 계획을 논의하지 않겠다는 뜻이다.","다음 달 회의를 취소하겠다는 뜻이다."],"goal":"진행 의도에 맞게 쟁점을 나누려면?","reply":"では、その件は別途検討し、まず販売計画の議論に戻りましょう。","wrongReplies":[{"text":"販売計画は扱わず、別件だけを話しましょう。","why":"우선 의제와 반대다."},{"text":"すべての議題を今すぐ中止しましょう。","why":"논의 범위를 조정하는 것이 아니라 전부 중지한다."},{"text":"来月は販売しないと決定します。","why":"논의하지 않은 결정을 임의로 내린다."}],"explanation":"「まず」가 우선순위를 나타낸다. 다른 사안의 중요성을 부정하지 않으면서 의제로 돌아간다.","formal":"その点は別の機会に検討することとし、本日の主題である販売計画に戻ってもよろしいでしょうか。","internal":"その件は別で話して、先に販売計画を決めましょう。","pattern":"その件は別途検討し、まず[本日の議題]の議論に戻りましょう。"},{"id":"biz-027","category":"meeting","title":"잠정 합의 요약","level":4,"setting":"두 안 중 한 안을 우선 검토하기로 했다.","dialogue":[{"speaker":"상대","voice":"female","text":"費用だけなら案エーですが、運用面では案ビーにも利点があります。今日は案エーを軸に、条件を詰めるところまでにしましょう。"}],"meaning":"A안을 중심으로 조건을 구체화하되 최종 확정까지 한 것은 아니다.","wrongMeanings":["B안을 최종 채택했다.","A안은 검토 대상에서 완전히 빠졌다.","두 안 모두 즉시 실행하기로 했다."],"goal":"합의 내용을 정확히 정리하려면?","reply":"本日は案エーを中心に条件を整理し、最終決定はその後、という理解でよろしいでしょうか。","wrongReplies":[{"text":"本日から両方の案を同時に実行します。","why":"동시 실행으로 합의한 것이 아니다."},{"text":"案ビーを正式採用したと共有します。","why":"선택한 검토 축이 다르다."},{"text":"案エーの検討を全面的に中止します。","why":"A안을 중심으로 논의한다는 내용과 반대다."}],"explanation":"「軸に」「条件を詰めるところまで」는 검토 방향과 오늘의 범위를 나타낸다.","formal":"案エーをベースに条件を具体化し、その結果を踏まえて最終判断する、という整理でよろしいでしょうか。","internal":"今日はA案の条件を詰めて、最終判断はその後ということですね。","pattern":"[案]を中心に条件を整理し、最終決定は[条件]の後という理解でよろしいでしょうか。"},{"id":"biz-028","category":"meeting","title":"결정권과 제안 구분","level":5,"setting":"회의에서 부서 간 제안은 모였지만 승인권자가 참석하지 않았다.","dialogue":[{"speaker":"나","voice":"male","text":"予算について、この場でお約束いただくことは可能でしょうか。"},{"speaker":"상대","voice":"female","text":"方向性としては賛成です。ただ、予算の決裁は本部長ですので、この場では確約できません。私から相談しておきます。"}],"meaning":"방향에는 찬성하지만 예산 결정권은 본부장에게 있어 현재 확약할 수 없다.","wrongMeanings":["예산이 이미 승인됐다는 뜻이다.","제안 방향 자체를 반대한다는 뜻이다.","참석자에게 본부장 승인 없이 집행하라는 뜻이다."],"goal":"본부장 확인을 기다린 뒤 확정하겠다고 답하려면?","reply":"ありがとうございます。それでは、本部長へのご確認後に、正式に決定する形で進めましょう。","wrongReplies":[{"text":"予算承認済みとして、本日発注します。","why":"찬성을 예산 승인으로 잘못 취급한다."},{"text":"方向性への反対として記録します。","why":"방향에는 찬성한다는 발언과 반대다."},{"text":"本部長への相談は不要です。","why":"결재권자의 승인을 생략하도록 한다."}],"explanation":"의견 찬성·예산 결재·실행 확약은 다르다. 「確約できない」의 범위를 정확히 이해한다.","formal":"ご相談いただきありがとうございます。正式なご判断をお待ちしたうえで、次の手続きを進めます。","internal":"ありがとうございます。本部長に確認してから正式決定にしましょう。","pattern":"[決裁者]への確認後に、正式に決定する形で進めましょう。"},{"id":"biz-029","category":"disagree","title":"반대 전에 공통 목적 확인","level":2,"setting":"동료가 고객 안내 절차를 전부 생략하자고 한다.","dialogue":[{"speaker":"상대","voice":"female","text":"時間を短縮したいので、事前の案内は省いて、そのまま作業を始めてはどうでしょうか。"}],"meaning":"시간을 줄이기 위해 사전 안내 없이 작업을 시작하자는 제안이다.","wrongMeanings":["사전 안내를 더 자세히 하자는 제안이다.","작업 자체를 중지하자는 제안이다.","작업 완료 후에 다시 사전 안내를 한다는 뜻이다."],"goal":"시간 절감에는 동의하되 안내 생략에는 반대하려면?","reply":"時間短縮の必要性には賛成ですが、事前案内は残したほうがよいと思います。","wrongReplies":[{"text":"事前案内をすべて削除することで合意ですね。","why":"반대하려는 내용에 동의한다."},{"text":"時間短縮は一切考えないでください。","why":"공통 목적 자체를 부정한다."},{"text":"作業はすでに完了しました。","why":"의견을 말하는 대신 다른 상태를 전달한다."}],"explanation":"공통 목적과 동의하지 않는 수단을 분리하면 의견 차이를 설명하기 쉽다.","formal":"効率化の趣旨は理解しておりますが、事前のご案内については継続すべきではないかと考えております。","internal":"時間短縮には賛成ですが、事前案内は残したいです。","pattern":"[目的]には賛成ですが、[方法]については再検討が必要だと思います。"},{"id":"biz-030","category":"disagree","title":"근거를 제시해 다른 안 제안","level":3,"setting":"팀원이 비용이 가장 낮은 외주 업체를 추천한다.","dialogue":[{"speaker":"상대","voice":"female","text":"一番安い会社にお願いすれば、予算は十分に抑えられると思います。"}],"meaning":"가격이 가장 낮은 업체를 쓰면 예산을 줄일 수 있다는 의견이다.","wrongMeanings":["가장 비싼 업체를 쓰자는 의견이다.","외주를 일절 쓰지 말자는 의견이다.","모든 업체의 납기가 같다고 확인한 것이다."],"goal":"납기 자료를 근거로 다른 관점을 제시하려면?","reply":"費用面では魅力的ですが、納期に差があるため、そちらも比較してはどうでしょうか。","wrongReplies":[{"text":"最も高い会社に、理由なく即決しましょう。","why":"근거 없는 즉결로 대화를 바꾼다."},{"text":"納期は確認していませんが、すべて同じと断定します。","why":"확인하지 않은 정보를 단정한다."},{"text":"予算を比較すること自体を禁止します。","why":"비용 장점을 인정하며 보완하려는 목적과 다르다."}],"explanation":"상대 안의 장점을 인정하고 비교 기준을 추가하는 방식이다. 가격이 싸다는 사실과 납기 적합성은 별개다.","formal":"コスト上の利点は理解しております。納期への影響も含めて比較検討するのはいかがでしょうか。","internal":"安さは魅力ですが、納期も比べてみませんか。","pattern":"[相手案の利点]は魅力的ですが、[別の判断基準]も比較してはどうでしょうか。"},{"id":"biz-031","category":"disagree","title":"사실 확인 전 단정 피하기","level":4,"setting":"동료가 거래처의 답장이 없다는 이유로 참여 의사가 없다고 추측한다.","dialogue":[{"speaker":"상대","voice":"female","text":"まだ返信がないので、先方は今回は参加しないつもりなのではないでしょうか。"}],"meaning":"답장이 없다는 사실을 근거로 상대의 불참 의사를 추측하고 있다.","wrongMeanings":["거래처가 불참을 공식 확정했다.","참가 신청이 이미 완료됐다.","거래처가 이번 행사를 주최한다."],"goal":"미확정임을 짚고 직접 확인하자고 제안하려면?","reply":"現時点では意向が確認できていませんので、まず先方に確認してみませんか。","wrongReplies":[{"text":"不参加が確定したとして、名簿から削除します。","why":"추측을 확정 사실로 바꾼다."},{"text":"先方は必ず参加すると確約します。","why":"참가도 확인되지 않았다."},{"text":"返信がない事実そのものは存在しません。","why":"관측된 사실까지 부정한다."}],"explanation":"「のではないでしょうか」는 이 문맥에서 추측이다. 답장 부재와 불참 확정을 구분한다.","formal":"先方のご意向は未確認ですので、結論を出す前に一度確認するのはいかがでしょうか。","internal":"まだ意向はわからないので、先に確認しませんか。","pattern":"現時点では[未確認の事項]が確認できていませんので、まず確認してみませんか。"},{"id":"biz-032","category":"disagree","title":"조건부 찬성의 범위 확인","level":5,"setting":"타 부서가 새 절차 도입에 조건부로 동의한다.","dialogue":[{"speaker":"나","voice":"male","text":"新しい手順の試行に、ご協力いただけますか。"},{"speaker":"상대","voice":"female","text":"試行には協力できます。ただし、全拠点で一度に始めるのではなく、まず二拠点で効果を確認したいと考えています。"}],"meaning":"시험 운영에 협력하되 우선 두 거점에서 효과를 보고 싶다는 뜻이다.","wrongMeanings":["모든 거점의 동시 도입에 무조건 동의했다.","시험 운영 협력을 전면 거절했다.","거점 수는 중요하지 않다고 말했다."],"goal":"조건을 반영해 합의점을 제시하려면?","reply":"まず二拠点で試行し、効果を確認してから対象を広げる方針でいかがでしょうか。","wrongReplies":[{"text":"では、全拠点で本日から一斉に導入します。","why":"시범 범위를 제한한 조건을 무시한다."},{"text":"試行そのものに反対ということで承りました。","why":"협력 가능하다는 핵심을 반대로 이해한다."},{"text":"効果の確認は省略して進めましょう。","why":"상대가 제시한 검증 조건을 생략한다."}],"explanation":"「ただし」 뒤의 조건을 포함해야 실제 합의다. 찬성의 범위를 임의로 넓히지 않는다.","formal":"まずは二拠点で検証し、その結果を踏まえて展開範囲を協議する形ではいかがでしょうか。","internal":"先に二拠点で試して、効果を見てから広げませんか。","pattern":"まず[限定した範囲]で試行し、[結果]を確認してから対象を広げませんか。"},{"id":"biz-033","category":"decline","title":"참석은 어렵지만 자료로 기여","level":2,"setting":"상대가 내일 회의 참석을 요청한다.","dialogue":[{"speaker":"상대","voice":"female","text":"明日の打ち合わせに参加いただけますか。難しければ、事前にご意見だけでもいただけると助かります。"}],"meaning":"참석이 어려우면 사전에 의견만 보내도 도움이 된다.","wrongMeanings":["반드시 직접 참석해야 한다.","의견은 회의 이후에만 받는다.","회의 자체가 취소됐다."],"goal":"참석은 어렵지만 의견서를 보내겠다고 답하려면?","reply":"あいにく参加は難しいのですが、事前に意見をまとめてお送りします。","wrongReplies":[{"text":"参加できませんので、意見も送りません。","why":"제시된 대안으로 기여하지 않는다."},{"text":"会議は中止と判断いたします。","why":"자신의 불참을 회의 취소로 바꾼다."},{"text":"会議終了後に、参加するか決めます。","why":"참석·사전 의견 중 어느 쪽에도 답하지 않는다."}],"explanation":"불참 사실과 가능한 협조를 함께 전한다. 「あいにく」는 사정이 맞지 않음을 완곡하게 말한다.","formal":"あいにく都合がつかず出席はかないませんが、事前に意見書をお送りいたします。","internal":"明日は出られませんが、先に意見を送ります。","pattern":"あいにく[依頼されたこと]は難しいのですが、[代わりにできること]は可能です。"},{"id":"biz-034","category":"decline","title":"즉답 대신 확인 시간 요청","level":3,"setting":"거래처가 추가 주문을 당장 확정해 달라고 한다.","dialogue":[{"speaker":"상대","voice":"female","text":"追加分についても、今日この場で確約いただくことはできますか。"}],"meaning":"추가분도 지금 확약할 수 있는지 묻는다.","wrongMeanings":["추가 주문 취소를 통보한다.","지금은 확약하지 말라는 뜻이다.","추가분 출하가 이미 완료됐다."],"goal":"재고 확인 후 오늘 17시까지 회신하겠다고 답하려면?","reply":"在庫の確認が必要ですので、この場では確約いたしかねます。本日十七時までにお返事いたします。","wrongReplies":[{"text":"確認していませんが、必ずすべて納品できます。","why":"확인되지 않은 납품을 확약한다."},{"text":"追加分はすでに発送済みです。","why":"현재 확인 중인 상태와 다르다."},{"text":"お返事は今後一切いたしません。","why":"응답 자체를 거절한다."}],"explanation":"「いたしかねます」로 지금 확약할 수 없음을 말하고 회신 기한을 제시한다.","formal":"恐れ入りますが、在庫確認前のお約束はいたしかねます。十七時までに確認結果をご連絡いたします。","internal":"在庫を確認したいので、十七時までに返事してもいいですか。","pattern":"[確認事項]が必要ですので、この場では確約いたしかねます。[期限]までにお返事します。"},{"id":"biz-035","category":"decline","title":"요구 범위 일부만 수락","level":4,"setting":"한 번에 두 가지 지원을 요청받았다.","dialogue":[{"speaker":"상대","voice":"female","text":"資料の翻訳と会議の通訳を、両方お願いすることはできますか。"}],"meaning":"자료 번역과 회의 통역을 둘 다 부탁하고 있다.","wrongMeanings":["회의 통역만 취소해 달라는 요청이다.","자료 검토만 부탁하는 요청이다.","번역 자료를 폐기해 달라는 요청이다."],"goal":"번역만 가능하고 통역은 어렵다고 분명히 답하려면?","reply":"資料の翻訳は対応できますが、会議の通訳は日程の都合で難しい状況です。","wrongReplies":[{"text":"どちらも対応可能です。","why":"수락 범위를 실제 가능 범위보다 넓힌다."},{"text":"翻訳も通訳も、すでに完了しております。","why":"아직 하지 않은 일을 완료로 말한다."},{"text":"翻訳には対応できませんが、通訳は可能です。","why":"가능한 업무와 불가능한 업무가 뒤바뀐다."}],"explanation":"일부만 수락할 때는 각 업무의 가능 여부를 나누어 말한다.","formal":"翻訳につきましては承れますが、通訳は日程が重なるため、今回はお引き受けいたしかねます。","internal":"翻訳はできますが、通訳は日程が重なって難しいです。","pattern":"[可能な業務]は対応できますが、[難しい業務]は[理由]で難しい状況です。"},{"id":"biz-036","category":"decline","title":"사양과 향후 가능성 구분","level":5,"setting":"거래처가 이번 행사 초대를 사양한다.","dialogue":[{"speaker":"나","voice":"male","text":"来週の交流会に、ぜひお越しいただけませんか。"},{"speaker":"상대","voice":"female","text":"せっかくお声がけいただいたのですが、今回は都合がつかず、見送らせていただければと思います。またの機会がございましたら、ぜひお願いいたします。"}],"meaning":"이번에는 사양하지만 다음 기회에는 참여하고 싶다는 뜻이다.","wrongMeanings":["이번 행사 참석을 확정했다.","앞으로 모든 초대를 거부한다.","행사 날짜를 바꿔 달라는 요청이다."],"goal":"이번 불참을 받아들이고 다음 기회를 약속하려면?","reply":"承知いたしました。また機会がございましたら、あらためてご案内いたします。","wrongReplies":[{"text":"ご出席確定として、お席を確保します。","why":"사양을 참석 확정으로 처리한다."},{"text":"今後は二度とご案内いたしません。","why":"다음 기회에 대한 의사를 무시한다."},{"text":"ご希望どおり、開催日を変更します。","why":"날짜 변경은 요청하지 않았다."}],"explanation":"「今回は」「またの機会」를 통해 거절의 범위가 이번 행사에 한정됨을 듣는다.","formal":"ご丁寧にご連絡いただきありがとうございます。またの機会にお声がけさせていただきます。","internal":"わかりました。また別の機会にご案内します。","pattern":"承知いたしました。また[次の機会]に、あらためてご案内いたします。"},{"id":"biz-037","category":"apology","title":"잘못된 파일을 보낸 뒤 수정","level":2,"setting":"거래처가 첨부 파일이 이전 버전이라고 알린다.","dialogue":[{"speaker":"상대","voice":"female","text":"添付いただいた資料ですが、更新前の版のようです。最新版をお送りいただけますか。"}],"meaning":"첨부된 파일이 이전 버전 같으니 최신본을 보내 달라는 요청이다.","wrongMeanings":["최신본을 받았으니 폐기해 달라는 요청이다.","파일을 종이로만 보내 달라는 요청이다.","버전에는 문제가 없다는 확인이다."],"goal":"실수를 인정하고 최신본을 재송부하려면?","reply":"失礼いたしました。最新版を確認のうえ、あらためてお送りいたします。","wrongReplies":[{"text":"古い版で確定ということで承りました。","why":"최신본 재송부 요청을 반대로 이해한다."},{"text":"ファイルの確認はせず、同じものを再送します。","why":"원인을 확인하지 않아 같은 문제가 반복된다."},{"text":"今後、資料の送付は一切取りやめます。","why":"이번 오류 수정을 넘어 자료 제공을 중단한다."}],"explanation":"사과와 수정 행동을 함께 말한다. 다시 보내기 전에 버전을 확인한다.","formal":"誤った版をお送りし、申し訳ございません。最新版を確認して再送いたします。","internal":"すみません。最新版か確認して、送り直します。","pattern":"[誤り]があり、申し訳ございません。[確認]のうえ、あらためてお送りします。"},{"id":"biz-038","category":"apology","title":"원인 미확정 상태에서 보고","level":3,"setting":"서비스 장애 원인을 아직 조사 중이다.","dialogue":[{"speaker":"상대","voice":"female","text":"不具合の原因は判明しましたか。いつごろ復旧する見込みでしょうか。"}],"meaning":"장애 원인과 복구 예상 시점을 묻고 있다.","wrongMeanings":["장애가 없었다고 확인한다.","복구 작업을 중단해 달라고 한다.","원인 조사는 필요 없다고 한다."],"goal":"원인 조사 중이며 30분 뒤 다시 알리겠다고 답하려면?","reply":"ご不便をおかけし申し訳ございません。現在調査中のため、三十分後にあらためて状況をご報告します。","wrongReplies":[{"text":"原因は確認していませんが、完全に解決済みです。","why":"확인되지 않은 해결을 단정한다."},{"text":"復旧作業はただちに中止いたします。","why":"복구 전망 질문을 작업 중단으로 바꾼다."},{"text":"原因が不明ですので、今後の報告もいたしません。","why":"후속 안내를 하지 않겠다는 내용이다."}],"explanation":"모르는 원인이나 복구 시각을 꾸며 확약하지 않는다. 조사 중이라는 상태와 다음 연락 시점을 말한다.","formal":"ご迷惑をおかけし、申し訳ございません。原因と復旧見込みを確認のうえ、三十分後を目途に続報をお伝えいたします。","internal":"申し訳ありません。原因と復旧見込みを調べ、三十分後にまた連絡します。","pattern":"現在[確認中の事項]を調査中です。[時刻]に続報をお伝えします。"},{"id":"biz-039","category":"apology","title":"내 사정과 상대 영향 함께 인정","level":4,"setting":"자신의 확인 누락으로 고객 승인이 늦어졌다.","dialogue":[{"speaker":"상대","voice":"female","text":"確認が一日遅れたことで、こちらの承認手続きも止まってしまいました。"}],"meaning":"하루 늦은 확인 때문에 상대 승인 절차도 중단됐다.","wrongMeanings":["상대는 지연 영향을 받지 않았다.","상대가 확인을 하루 먼저 끝냈다.","승인 절차가 이미 모두 완료됐다."],"goal":"내 누락이 미친 영향을 인정하며 사과하려면?","reply":"私の確認漏れにより、承認手続きに影響を及ぼしてしまい、申し訳ございません。","wrongReplies":[{"text":"そちらの手続きだけの問題で、当方に関係はありません。","why":"자신의 확인 누락과 영향을 인정하지 않는다."},{"text":"承認手続きへの影響は一切なかったということですね。","why":"상대가 설명한 영향을 반대로 이해한다."},{"text":"確認は予定より一日早く完了していました。","why":"실제 확인 지연과 다르다."}],"explanation":"상대에게 발생한 구체적인 영향을 언급하면 단순한 상투적 사과를 넘어 사실에 답할 수 있다.","formal":"当方の確認不足によりお手続きをお待たせすることとなり、誠に申し訳ございません。","internal":"こちらの確認漏れで手続きが止まってしまい、申し訳ありません。","pattern":"当方の[不備]により、[相手に生じた影響]を招き、申し訳ございません。"},{"id":"biz-040","category":"apology","title":"재발 방지에 구체적인 답","level":5,"setting":"같은 오류가 재발해 상대가 대책을 묻는다.","dialogue":[{"speaker":"나","voice":"male","text":"再発防止について、どのようなご要望がございますか。"},{"speaker":"상대","voice":"female","text":"前回も同じ誤りがありました。再発を防ぐために、どのような確認を追加される予定ですか。"}],"meaning":"같은 오류를 막기 위해 추가할 구체적인 확인 절차를 묻는다.","wrongMeanings":["재발 가능성에 대한 설명은 필요 없다는 뜻이다.","오류가 처음 발생했다는 확인이다.","단지 담당자의 사적 연락처를 묻는다."],"goal":"발송 전 이중 확인을 추가하겠다고 답하려면?","reply":"再発を防ぐため、送付前に担当者と別のメンバーが版と宛先を確認する手順を追加します。","wrongReplies":[{"text":"今後は気をつけます。それ以外は何も変えません。","why":"추가 확인 절차를 구체적으로 설명하지 않는다."},{"text":"確認者を減らし、確認自体を省略します。","why":"요청한 재발 방지와 반대 방향이다."},{"text":"同じ誤りは一度もなかったと訂正してください。","why":"이미 발생한 사실을 부인한다."}],"explanation":"대책을 요구받으면 태도 표명뿐 아니라 누가·언제·무엇을 확인할지 답한다.","formal":"送付前の版管理と宛先確認を二名で実施する運用に改め、再発防止を徹底いたします。","internal":"送る前に、別の人と二人で版と宛先を確認するようにします。","pattern":"再発を防ぐため、[時点]に[確認者]が[確認内容]を確認する手順を追加します。"},{"id":"biz-041","category":"reminder","title":"기한이 지난 회신 확인","level":2,"setting":"약속한 회신일이 지났지만 답을 받지 못했다.","dialogue":[{"speaker":"상대","voice":"female","text":"昨日までにお返事をお願いしていた件ですが、その後いかがでしょうか。"}],"meaning":"어제까지 요청한 회신의 현재 진행 상황을 묻는다.","wrongMeanings":["어제 답장을 받았다는 감사 인사다.","기한을 다음 달로 연장한다는 통보다.","회신하지 않아도 된다는 뜻이다."],"goal":"오늘 15시까지 회신하겠다고 답하려면?","reply":"お返事が遅くなり申し訳ございません。本日十五時までにご連絡いたします。","wrongReplies":[{"text":"昨日ご返信いただき、ありがとうございました。","why":"회신을 받은 입장으로 바뀐다."},{"text":"ご連絡は不要とのことで承知しました。","why":"독촉을 회신 불필요로 이해한다."},{"text":"いつか確認しますので、時期はお伝えしません。","why":"요청에 대한 구체적인 회신 계획이 없다."}],"explanation":"「その後いかがでしょうか」는 이 맥락에서 진행 확인을 겸한 완곡한 독촉이다.","formal":"ご回答が遅れており、申し訳ございません。十五時までに確認のうえ、ご回答申し上げます。","internal":"返事が遅くなってすみません。今日十五時までに連絡します。","pattern":"お返事が遅くなり申し訳ございません。[期限]までにご連絡いたします。"},{"id":"biz-042","category":"reminder","title":"여러 업무의 우선순위 확인","level":3,"setting":"상사에게 두 업무를 동시에 받았고 같은 시간 안에 끝내기 어렵다.","dialogue":[{"speaker":"상대","voice":"female","text":"新しい見積書も急ぎですが、午後の会議資料も必要です。まず、どこまで対応できそうですか。"}],"meaning":"견적서와 회의 자료 모두 급하므로 처리 가능한 범위를 묻는다.","wrongMeanings":["회의 자료는 더 이상 필요 없다.","견적서 작업을 완전히 취소했다.","두 업무가 이미 완료됐다고 확인한다."],"goal":"충돌을 알리고 우선순위를 확인하려면?","reply":"両方を同時に仕上げるのは難しいため、どちらを優先すべきかご相談してもよろしいでしょうか。","wrongReplies":[{"text":"どちらも完了したと報告します。","why":"미완료 업무를 완료로 보고한다."},{"text":"確認せず、両方とも中止します。","why":"상의 없이 필요한 업무를 모두 중단한다."},{"text":"会議資料は不要になったということですね。","why":"아직 필요하다는 내용과 반대다."}],"explanation":"혼자 우선순위를 단정하기보다 처리 한계를 알리고 필요한 판단을 요청한다.","formal":"期限が重なっておりますので、優先順位をご指示いただけますでしょうか。","internal":"両方を同時に終えるのは難しいのですが、どちらを先にしますか。","pattern":"[制約]があるため、[選択肢]のどちらを優先すべきかご相談してもよろしいでしょうか。"},{"id":"biz-043","category":"reminder","title":"기한 연장을 구체적으로 요청","level":4,"setting":"추가 검증 때문에 당일 제출이 어렵다.","dialogue":[{"speaker":"상대","voice":"female","text":"追加の検証が必要になりました。今日中の提出は難しい見込みですが、明日の午前中には確認を終えられます。"}],"meaning":"오늘 제출은 어렵지만 내일 오전에는 검증을 마칠 수 있다.","wrongMeanings":["검증은 이미 완료돼 오늘 제출할 수 있다.","내일 오전까지도 검증을 시작할 수 없다.","추가 검증이 필요 없다는 뜻이다."],"goal":"제출 기한을 내일 정오로 연장받으려면?","reply":"追加検証のため、提出期限を明日の正午まで延ばしていただくことは可能でしょうか。","wrongReplies":[{"text":"本日中の提出はすでに完了しました。","why":"예상 상태와 다르다."},{"text":"検証は一切行わず、提出を取りやめます。","why":"검증 후 제출한다는 계획과 다르다."},{"text":"期限を延ばさず、来週に提出すると決定しました。","why":"동의 없이 약속을 변경한다."}],"explanation":"연장 요청에는 이유와 새 기한을 함께 제시하고 상대의 수락을 확인한다.","formal":"恐れ入りますが、検証の完了を待つため、明日正午までお時間を頂戴できますでしょうか。","internal":"追加検証があるので、締め切りを明日の正午に延ばしてもらえますか。","pattern":"[理由]のため、期限を[新しい期限]まで延ばしていただくことは可能でしょうか。"},{"id":"biz-044","category":"reminder","title":"최종본보다 필요한 일부 먼저","level":5,"setting":"거래처가 최종 보고서는 늦어도 되지만 수치는 먼저 달라고 한다.","dialogue":[{"speaker":"나","voice":"male","text":"報告書は、すべて明日までに必要でしょうか。"},{"speaker":"상대","voice":"female","text":"報告書全体は来週でも構いません。ただ、予算会議で使う売上の数字だけは、明日の午前中に必要です。"}],"meaning":"전체 보고서는 다음 주도 가능하지만 매출 수치는 내일 오전 필요하다.","wrongMeanings":["모든 자료를 다음 주에만 보내면 된다.","전체 보고서를 오늘까지 완성해야 한다.","매출 수치는 보내지 않아도 된다."],"goal":"우선 수치를 보내고 전체 보고서를 나중에 보내겠다고 확인하려면?","reply":"売上の数値を明日の午前中に先行してお送りし、報告書全体は来週お送りします。","wrongReplies":[{"text":"すべて来週まとめてお送りします。","why":"먼저 필요한 수치의 기한을 놓친다."},{"text":"売上の数値は報告書から削除します。","why":"요청한 핵심 정보를 없앤다."},{"text":"本日中に全体の最終版を確定したと報告します。","why":"요청보다 빠른 목표가 아니라 미완료 상태를 완료로 말한다."}],"explanation":"「全体は…ただ…だけは」 구조에서는 우선 필요한 범위와 기한이 다르다.","formal":"必要な売上数値のみ明日午前中に先行共有し、報告書一式は来週提出いたします。","internal":"数字だけ明日の午前中に先に送り、全体は来週送ります。","pattern":"[先に必要な部分]を[早い期限]に先行してお送りし、全体は[後の期限]にお送りします。"},{"id":"biz-045","category":"email","title":"첨부 누락 재송부","level":2,"setting":"거래처가 메일은 받았지만 첨부가 없다고 알린다.","dialogue":[{"speaker":"상대","voice":"female","text":"メールは届いておりますが、添付ファイルが見当たりません。お手数ですが、再送をお願いいたします。"}],"meaning":"메일은 수신했으나 첨부가 없어 다시 보내 달라는 요청이다.","wrongMeanings":["메일과 첨부 모두 정상 수신했다.","메일 주소를 폐기해 달라는 요청이다.","종이 원본을 이미 수령했다."],"goal":"첨부 누락을 인정하고 다시 보내려면?","reply":"添付が漏れており、失礼いたしました。ファイルを添付して再送いたします。","wrongReplies":[{"text":"添付は不要とのことで、再送はいたしません。","why":"첨부 재송부 요청과 반대다."},{"text":"メール自体も届いていないということですね。","why":"메일은 도착했다는 정보를 놓친다."},{"text":"宛先を確認せず、全社へ転送します。","why":"요청하지 않은 광범위한 전달을 한다."}],"explanation":"메일 미수신과 첨부 누락을 구분한다. 누락된 파일을 붙여 재전송한다.","formal":"添付漏れがあり、申し訳ございません。あらためてファイルを添付のうえ、再送いたします。","internal":"添付を忘れていました。すみません、付けて送り直します。","pattern":"[添付／記載]が漏れており、失礼いたしました。[修正内容]して再送いたします。"},{"id":"biz-046","category":"email","title":"참조와 주 수신자 구분","level":3,"setting":"진행 보고 메일의 수신 방식을 안내받는다.","dialogue":[{"speaker":"상대","voice":"female","text":"回答は担当の森さんに直接送り、私は参照に入れておいてください。"}],"meaning":"답변은 모리에게 직접 보내고 말한 사람은 참조에 넣는다.","wrongMeanings":["말한 사람에게만 보내고 모리는 제외한다.","모든 사람을 비공개 참조에만 넣는다.","답변을 보내지 말라는 뜻이다."],"goal":"수신 방식에 동의하려면?","reply":"森さんを宛先にして、ご指定のアドレスを参照に入れてお送りします。","wrongReplies":[{"text":"森さんには送らず、参照からも外します。","why":"주 수신자를 제외한다."},{"text":"宛先は確認せず、関係のない方にも送ります。","why":"안내한 수신 범위와 다르다."},{"text":"ご回答自体を取りやめます。","why":"전달 방식 안내를 발송 취소로 바꾼다."}],"explanation":"「直接送る相手」와 「参照に入れる相手」가 다르다. 업무 담당자에게 직접 응답하는 구조다.","formal":"森様を主な宛先とし、ご指定のメールアドレスを参照先に加えてお送りいたします。","internal":"森さん宛てで、こちらはCCに入れて送ります。","pattern":"[担当者]を宛先にして、[共有先]を参照に入れてお送りします。"},{"id":"biz-047","category":"email","title":"차이만 표시한 수정본","level":4,"setting":"상대가 전체 자료 대신 수정 부분을 파악하고 싶어 한다.","dialogue":[{"speaker":"상대","voice":"female","text":"前回から変更した箇所がわかるようにしていただけますか。すべて読み直す時間が取れなくて。"}],"meaning":"전체를 다시 읽기 어려우니 지난번과 달라진 부분을 표시해 달라는 요청이다.","wrongMeanings":["변경 표시를 모두 삭제해 달라는 요청이다.","이전 버전만 다시 보내 달라는 요청이다.","내용 수정 자체를 금지한다는 뜻이다."],"goal":"변경 부분을 표시해 보내겠다고 답하려면?","reply":"変更箇所に印を付けた修正版をお送りします。","wrongReplies":[{"text":"変更箇所の印はすべて消しておきます。","why":"요청한 표시를 반대로 지운다."},{"text":"前回と同じ資料だけを再送します。","why":"현재 수정 내용을 전달하지 않는다."},{"text":"資料全体の確認時間を確保したものとします。","why":"상대에게 읽을 시간이 없다는 조건을 무시한다."}],"explanation":"「変更した箇所がわかるように」는 변경 식별을 쉽게 해 달라는 말이다.","formal":"前回版との差分がわかるよう、変更箇所を明示して再送いたします。","internal":"変えたところに印を付けて、送り直します。","pattern":"[比較対象]からの変更箇所を明示した[修正版]をお送りします。"},{"id":"biz-048","category":"email","title":"외부 공유 가능한 판본 구분","level":5,"setting":"내부용과 외부용 파일이 따로 있다.","dialogue":[{"speaker":"나","voice":"male","text":"先方には、どの資料をお送りすればよろしいですか。"},{"speaker":"상대","voice":"female","text":"社内検討用の資料には、まだ確定していない数字が含まれています。先方には、確定値のみを載せた共有用の版をお送りください。"}],"meaning":"외부에는 잠정 수치가 없는 확정치만 담은 공유용 파일을 보내야 한다.","wrongMeanings":["내부 검토용을 그대로 외부에 보내야 한다.","확정 수치를 모두 삭제하라는 요청이다.","어떤 판본이든 동일하게 공유해도 된다."],"goal":"외부용 파일을 확인해 발송하겠다고 답하려면?","reply":"確定値のみを記載した共有用の版であることを確認してから、先方に送付します。","wrongReplies":[{"text":"未確定の数字を含む社内版を、そのまま送ります。","why":"사외 공유용 판본 지시를 지키지 않는다."},{"text":"すべての確定値を削除してから送ります。","why":"필요한 확정 수치를 오히려 없앤다."},{"text":"どの版でも同じなので、確認は省きます。","why":"판본에 따른 차이를 무시한다."}],"explanation":"자료가 여러 개일 때는 파일명만이 아니라 포함 정보와 공유 대상을 확인한다.","formal":"社外共有用であることと記載数値の確定状況を確認のうえ、送付いたします。","internal":"確定値だけの共有版か確認してから送ります。","pattern":"[共有先]向けの版であることを確認してから、送付します。"},{"id":"biz-049","category":"remote","title":"음성이 끊겨 다시 말해 달라고 요청","level":2,"setting":"온라인 회의 중 소리가 끊겼다.","dialogue":[{"speaker":"상대","voice":"female","text":"次の議題ですが、来月の担当者を決めたいと思います。こちらの声は届いていますか。"}],"meaning":"다음 달 담당자를 정하려 하며 음성이 들리는지 확인한다.","wrongMeanings":["다음 달 회의를 취소한다.","소리가 잘 들린다고 상대가 확정했다.","담당자가 이미 정해졌다는 통보다."],"goal":"잘 안 들렸으니 마지막 부분을 반복해 달라고 하려면?","reply":"少し音声が途切れてしまいました。最後の部分をもう一度お願いできますか。","wrongReplies":[{"text":"音声は一度も途切れておりません。","why":"실제 듣기 문제를 전달하지 않는다."},{"text":"担当者の決定は完了しました。","why":"들은 내용을 확인하는 대신 확정을 말한다."},{"text":"ご参加を取りやめていただきます。","why":"반복 요청 대신 상대의 참석을 취소한다."}],"explanation":"통신 문제와 필요한 반복 범위를 구체적으로 말한다.","formal":"恐れ入ります。音声が一部途切れましたので、最後のご説明をもう一度お聞かせいただけますでしょうか。","internal":"少し音が切れたので、最後のところをもう一度お願いします。","pattern":"[聞こえなかった理由]のため、[必要な部分]をもう一度お願いできますか。"},{"id":"biz-050","category":"remote","title":"화면 공유의 보기와 조작 권한 구분","level":3,"setting":"상대가 공유 자료가 보이는지 묻는다.","dialogue":[{"speaker":"상대","voice":"female","text":"資料は画面共有だけですので、皆さんの側から編集はできません。修正点があれば、口頭でお知らせください。"}],"meaning":"참석자는 직접 편집할 수 없고 수정 사항을 말로 알려야 한다.","wrongMeanings":["참석자가 즉시 원본을 수정해야 한다.","수정 의견은 받지 않는다.","공유 자료 자체를 볼 수 없다는 뜻이다."],"goal":"두 번째 페이지에 대한 수정 의견을 말하려면?","reply":"二ページ目について、一点修正をお願いしてもよろしいでしょうか。","wrongReplies":[{"text":"こちらで原本を編集済みです。","why":"직접 편집할 수 없다는 조건과 맞지 않는다."},{"text":"修正点は共有しないでおきます。","why":"구두로 알려 달라는 요청에 응하지 않는다."},{"text":"画面共有は存在しないということですね。","why":"공유는 되고 있다는 정보와 반대다."}],"explanation":"화면을 볼 수 있는 것과 원본을 수정할 수 있는 것은 다르다.","formal":"恐れ入りますが、二ページ目の記載について、一箇所修正をお願いできますでしょうか。","internal":"二ページ目を一か所直してもらえますか。","pattern":"[ページ／箇所]について、一点修正をお願いしてもよろしいでしょうか。"},{"id":"biz-051","category":"remote","title":"중간 퇴실 뒤 필요한 정보 요청","level":4,"setting":"다른 일정으로 온라인 회의 후반에 참석하지 못한다.","dialogue":[{"speaker":"상대","voice":"female","text":"途中でご退出される方には、決定事項と担当の割り振りを、後ほどチャットで共有します。"}],"meaning":"중간 퇴실자에게 나중에 결정 사항과 역할 분담을 채팅으로 공유한다.","wrongMeanings":["회의 전체가 즉시 끝난다.","중간 퇴실자는 이후 정보를 받을 수 없다.","퇴실자가 모든 결정을 독자적으로 해야 한다."],"goal":"다음 행동까지 함께 공유해 달라고 부탁하려면?","reply":"ありがとうございます。決定事項に加えて、次に対応する内容も共有いただけますか。","wrongReplies":[{"text":"共有は不要ですので、担当だけ外してください。","why":"후속 정보를 받고 싶다는 목적과 다르다."},{"text":"会議が中止になったと全員に伝えます。","why":"퇴실 안내를 회의 취소로 이해한다."},{"text":"決定事項は共有せず、削除をお願いします。","why":"공유 제안과 반대다."}],"explanation":"후속 공유를 수락하며 자신이 실행할 업무까지 요청한다.","formal":"ご配慮ありがとうございます。決定事項とあわせて、対応事項もお知らせいただけますと幸いです。","internal":"ありがとうございます。次にやることも一緒に送ってもらえますか。","pattern":"[お礼]。[共有内容]に加えて、[必要な追加情報]も共有いただけますか。"},{"id":"biz-052","category":"remote","title":"비동기 업무의 회신 기한","level":5,"setting":"재택근무 팀의 연락 원칙을 확인한다.","dialogue":[{"speaker":"나","voice":"male","text":"チャットの返信時期について、チームのルールはありますか。"},{"speaker":"상대","voice":"female","text":"急ぎでなければ、チャットの返答は当日中で構いません。ただし、対応期限がある依頼は、その期限を必ず書いてください。"}],"meaning":"급하지 않은 채팅은 당일 중 회신해도 되지만 기한이 있는 요청에는 기한을 명시해야 한다.","wrongMeanings":["모든 채팅을 즉시 답해야 한다.","기한 있는 요청도 기한을 쓰지 말아야 한다.","채팅으로 업무 요청하는 것이 금지됐다."],"goal":"앞으로 기한이 있는 요청에 적용하겠다고 답하려면?","reply":"承知しました。期限のある依頼には、対応いただきたい日時を明記します。","wrongReplies":[{"text":"すべて即時回答が必須ということで共有します。","why":"긴급하지 않은 연락의 유예를 무시한다."},{"text":"期限がある場合も、あえて記載を省きます。","why":"필수 기재 사항을 생략한다."},{"text":"チャットでの依頼は全面的に取りやめます。","why":"연락 원칙을 금지로 바꾼다."}],"explanation":"기본 규칙과 예외를 모두 듣는다. 「ただし」 뒤의 기한 명시가 핵심이다.","formal":"期日のあるご依頼については、ご対応をお願いしたい日時を明示いたします。","internal":"期限がある依頼には、いつまでか必ず書きます。","pattern":"[条件]のある依頼には、[必要な情報]を明記します。"},{"id":"biz-053","category":"pricing","title":"세금 포함 여부 확인","level":2,"setting":"견적 금액의 기준을 듣는다.","dialogue":[{"speaker":"상대","voice":"female","text":"お見積もりの金額は税抜きです。送料は別途となっております。"}],"meaning":"견적은 세금 별도이며 배송비도 별도다.","wrongMeanings":["세금과 배송비가 모두 포함됐다.","세금만 포함되고 배송비는 무료다.","배송비만 포함되고 세금이 무료다."],"goal":"세금과 배송비 포함 총액을 요청하려면?","reply":"税込みで、送料も含めた総額をお知らせいただけますか。","wrongReplies":[{"text":"送料込みの税込総額が提示済みということですね。","why":"아직 별도인 항목을 포함으로 이해한다."},{"text":"送料だけを除いた金額で、最終確定します。","why":"총액을 알고 싶다는 목적을 충족하지 못한다."},{"text":"注文した商品はすべて返品します。","why":"금액 기준 확인과 관계없는 반환이다."}],"explanation":"「税抜き」「別途」는 최종 지불액에 추가될 항목을 나타낸다.","formal":"消費税および送料を含めた最終的な合計金額をご提示いただけますでしょうか。","internal":"税込みで、送料込みだと全部でいくらになりますか。","pattern":"[追加項目]も含めた総額をお知らせいただけますか。"},{"id":"biz-054","category":"pricing","title":"예산 내 범위 조정","level":3,"setting":"제안 금액이 예산을 넘지만 기능을 줄일 수 있다.","dialogue":[{"speaker":"상대","voice":"female","text":"機能をすべて付けると、ご予算を上回ります。必要な機能に絞れば、予算内に収めることも可能です。"}],"meaning":"필요한 기능으로 제한하면 예산 안에 맞출 수 있다.","wrongMeanings":["기능을 줄여도 금액은 절대 바뀌지 않는다.","모든 기능이 이미 예산 내에 들어간다.","예산과 관계없이 계약이 확정됐다."],"goal":"필수 기능만 남긴 견적을 요청하려면?","reply":"それでは、必須の機能に絞った場合のお見積もりをお願いできますか。","wrongReplies":[{"text":"すべての機能が予算内と確認できました。","why":"모두 포함하면 초과한다는 내용을 놓친다."},{"text":"予算を確認せず、すべて契約済みとします。","why":"아직 협의 중인 내용을 계약 확정으로 바꾼다."},{"text":"必要な機能もすべて削除してください。","why":"필수 기능을 남겨 조정하려는 목적과 다르다."}],"explanation":"가격 자체를 무조건 깎아 달라는 요청과 제공 범위를 줄인 재견적은 다르다.","formal":"必須機能のみを対象とした場合の費用を、あらためてご提示いただけますでしょうか。","internal":"必要な機能だけにした見積もりを出してもらえますか。","pattern":"[必要な範囲]に絞った場合のお見積もりをお願いできますか。"},{"id":"biz-055","category":"pricing","title":"한 번만 적용되는 할인","level":4,"setting":"할인 조건을 확인한다.","dialogue":[{"speaker":"상대","voice":"female","text":"今回の割引は初回のご注文に限ります。二回目以降は、通常のお取引条件が適用されます。"}],"meaning":"할인은 첫 주문만 적용되고 이후는 통상 거래 조건이다.","wrongMeanings":["할인은 모든 주문에 영구 적용된다.","할인은 두 번째 주문부터 시작한다.","첫 주문에는 할인이 적용되지 않는다."],"goal":"두 번째 주문의 가격을 다시 확인하려면?","reply":"二回目以降は通常価格になるとのことですが、その条件でのお見積もりもいただけますか。","wrongReplies":[{"text":"二回目から割引が始まるということですね。","why":"할인 적용 순서가 반대다."},{"text":"全注文で同じ割引が続くものとして発注します。","why":"첫 주문 한정 조건을 무시한다."},{"text":"初回の割引は適用しないでください。","why":"다음 주문 가격 확인이라는 목적과 다르다."}],"explanation":"「限る」「以降」를 통해 적용 범위를 듣는다. 첫 주문 가격을 이후 거래에 그대로 대입하지 않는다.","formal":"次回以降に適用される通常条件での価格表も、ご共有いただけますでしょうか。","internal":"次から通常価格とのことなので、その見積もりももらえますか。","pattern":"[適用期間]以降は[通常条件]とのことですが、その条件のお見積もりもいただけますか。"},{"id":"biz-056","category":"pricing","title":"조건부 가격 수락","level":5,"setting":"공급업체가 가격을 유지할 수 있는 조건을 제시한다.","dialogue":[{"speaker":"나","voice":"male","text":"今回も、前回と同じ単価でお願いすることは可能でしょうか。"},{"speaker":"상대","voice":"female","text":"同じ単価での対応は可能ですが、発注数量が百個以上で、納期に一週間の余裕をいただけることが条件です。"}],"meaning":"100개 이상 주문하고 납기에 일주일 여유를 주면 같은 단가가 가능하다.","wrongMeanings":["수량과 납기에 관계없이 같은 단가다.","100개 미만이며 즉시 납품할 때만 같은 단가다.","단가를 올리면 100개 이상 주문할 수 없다."],"goal":"두 조건을 받아들이며 재확인하려면?","reply":"百個以上で発注し、納期を一週間延ばせば、同じ単価で対応いただけるということですね。","wrongReplies":[{"text":"百個未満で本日納品でも同じ単価、ということですね。","why":"수량과 납기 조건을 모두 위반한다."},{"text":"百個以上なら、納期の条件は不要ということですね。","why":"두 조건 중 납기 조건을 누락한다."},{"text":"納期だけ延ばせば、数量条件はないということですね。","why":"수량 조건을 누락한다."}],"explanation":"「ですが」「条件」 뒤에 제시된 두 요건을 모두 포함해 복창한다.","formal":"数量を百個以上とし、納期に一週間の余裕を設けることで、現行単価を維持いただけるとの理解でよろしいでしょうか。","internal":"百個以上で、一週間納期を延ばせば、同じ単価ですね。","pattern":"[条件一]と[条件二]を満たせば、[希望条件]で対応いただけるということですね。"},{"id":"biz-057","category":"delivery","title":"출하일과 도착일 구분","level":2,"setting":"상품 발송 일정을 안내받는다.","dialogue":[{"speaker":"상대","voice":"female","text":"金曜日に出荷予定ですので、お届けは翌週の月曜日になる見込みです。"}],"meaning":"금요일 출하, 다음 주 월요일 도착 예상이다.","wrongMeanings":["금요일에 도착한다.","월요일에 출하해 금요일에 도착한다.","금요일 출하가 이미 완료됐다."],"goal":"월요일 도착 예정으로 이해했다고 답하려면?","reply":"月曜日に到着予定ということで承知いたしました。","wrongReplies":[{"text":"金曜日までに到着するということで手配します。","why":"출하일을 도착일로 바꾼다."},{"text":"月曜日に出荷するということですね。","why":"출하일이 다르다."},{"text":"すでに受け取りが完了しました。","why":"예정된 배송을 수령 완료로 말한다."}],"explanation":"「出荷」와 「お届け」는 다른 시점이다. 「見込み」는 전망이다.","formal":"翌週月曜日のお届け見込みとのことで承知いたしました。","internal":"到着は来週月曜の予定ですね。","pattern":"[到着日]に到着予定ということで承知いたしました。"},{"id":"biz-058","category":"delivery","title":"가능한 수량부터 분할 납품","level":3,"setting":"총 80개 주문 중 일부만 즉시 출하할 수 있다.","dialogue":[{"speaker":"상대","voice":"female","text":"八十個のうち、五十個は本日出荷できます。残り三十個は、来週の入荷後になります。"}],"meaning":"50개는 오늘 출하 가능하고 나머지 30개는 다음 주 입고 후 가능하다.","wrongMeanings":["80개 전부 오늘 출하 가능하다.","30개는 오늘, 50개는 다음 주에 가능하다.","전체 주문이 취소됐다."],"goal":"50개를 먼저 보내고 나머지는 나중에 받으려면?","reply":"それでは、五十個を先に出荷いただき、残りは入荷後にお送りいただけますか。","wrongReplies":[{"text":"八十個すべてを本日発送済みとします。","why":"가능 수량을 넘어 완료 처리한다."},{"text":"三十個を先に、五十個は入荷後にお願いします。","why":"현재 재고와 나머지 수량이 뒤바뀐다."},{"text":"分納ではなく、注文をすべて取り消します。","why":"분할 수령하려는 목적과 다르다."}],"explanation":"「うち」「残り」로 부분 수량을 파악한다. 「先に」를 이용해 분납 순서를 정할 수 있다.","formal":"在庫のある五十個を先行出荷いただき、残数は入荷次第お手配いただけますでしょうか。","internal":"五十個を先に送り、残りは入荷後に送ってもらえますか。","pattern":"[用意できる数量]を先に出荷いただき、残りは[条件]の後にお送りいただけますか。"},{"id":"biz-059","category":"delivery","title":"대체품 사용 전 사양 확인","level":4,"setting":"원래 부품 대신 호환 부품을 제안받았다.","dialogue":[{"speaker":"상대","voice":"female","text":"同等品でしたら在庫があります。ただ、寸法が一部異なりますので、ご使用条件に合うかご確認ください。"}],"meaning":"대체품 재고는 있지만 일부 치수가 달라 사용 조건 확인이 필요하다.","wrongMeanings":["대체품은 치수가 완전히 같다고 보증했다.","대체품 재고는 없다.","사용 조건을 확인할 필요가 없다는 뜻이다."],"goal":"사양서를 받아 확인한 뒤 주문을 결정하려면?","reply":"先に仕様書をお送りいただけますか。使用条件を確認してから、発注を判断いたします。","wrongReplies":[{"text":"寸法は完全に同じとのことで、確認せずに発注します。","why":"차이가 있다는 안내를 무시한다."},{"text":"在庫がないということで、代替案は不要です。","why":"대체품 재고가 있다는 정보와 다르다."},{"text":"使用条件に合うかどうかは、納品後まで確認しません。","why":"사전 검토가 필요한 조건을 뒤로 미룬다."}],"explanation":"「同等品」이 모든 치수와 사용 조건이 동일하다는 뜻은 아니다.","formal":"ご提案ありがとうございます。仕様書を拝見し、使用条件との適合を確認したうえで判断いたします。","internal":"まず仕様書を見て、使えるか確認してから発注を決めます。","pattern":"[資料]をお送りいただけますか。[必要な条件]を確認してから判断します。"},{"id":"biz-060","category":"delivery","title":"최종 고객 기한을 기준으로 조율","level":5,"setting":"출하를 앞당기기 어렵지만 배송 수단을 바꿀 수 있다.","dialogue":[{"speaker":"나","voice":"male","text":"お届けまでの日数を、少しでも短縮できますか。"},{"speaker":"상대","voice":"female","text":"出荷日を早めるのは難しいのですが、配送方法を変更すれば、到着を一日早められる可能性があります。追加費用を確認してみましょうか。"}],"meaning":"출하는 앞당기기 어렵지만 배송 방법 변경으로 도착을 하루 앞당길 가능성이 있다.","wrongMeanings":["출하와 도착 모두 하루 앞당긴다고 확약했다.","추가 비용 없이 도착을 반드시 앞당긴다.","배송 수단을 변경할 수 없다는 뜻이다."],"goal":"비용과 도착 가능일을 확인한 뒤 판단하려면?","reply":"追加費用と到着予定日をご確認いただけますか。その結果を踏まえて判断したいと思います。","wrongReplies":[{"text":"追加費用なしで必ず早着すると確定します。","why":"가능성을 보장으로 바꾸고 비용까지 단정한다."},{"text":"出荷日を早めることで合意済みとします。","why":"어렵다고 한 출하일 변경으로 이해한다."},{"text":"費用は確認せず、どのような金額でも承諾します。","why":"검토 후 판단하려는 목적과 다르다."}],"explanation":"「可能性」「確認してみましょうか」는 확인 전 제안이다. 비용과 일정 확인 뒤 결정한다.","formal":"恐れ入りますが、追加費用と短縮後の到着見込みをご確認いただいたうえで、ご相談できますでしょうか。","internal":"追加料金と到着日を調べてもらい、見てから決めたいです。","pattern":"[判断に必要な条件]をご確認いただけますか。その結果を踏まえて判断します。"},{"id":"biz-061","category":"handover","title":"담당자 변경 안내","level":2,"setting":"거래처가 다음 달부터 문의할 담당자를 안내한다.","dialogue":[{"speaker":"상대","voice":"female","text":"来月から窓口が佐々木に変わります。今月中のご連絡は、これまでどおり私宛てにお願いいたします。"}],"meaning":"이번 달은 기존 담당자, 다음 달부터 사사키가 창구다.","wrongMeanings":["오늘부터 모든 연락이 사사키에게 바뀐다.","다음 달에도 기존 담당자에게만 연락한다.","문의 창구가 완전히 폐쇄된다."],"goal":"연락처 변경 시점을 복창하려면?","reply":"今月中はこれまでのご担当者様、来月からは佐々木様宛てということで承知しました。","wrongReplies":[{"text":"本日からすべて佐々木様にお送りします。","why":"적용 시점이 이르다."},{"text":"来月からも佐々木様には連絡いたしません。","why":"새 창구를 반영하지 않는다."},{"text":"お問い合わせを受け付けないということですね。","why":"담당 변경을 창구 폐쇄로 이해한다."}],"explanation":"담당자 이름뿐 아니라 적용 시작일을 함께 듣는다.","formal":"今月は従来の窓口、来月以降は佐々木様にご連絡する旨、承知いたしました。","internal":"今月は今の担当者、来月から佐々木さんですね。","pattern":"[期間一]は[窓口一]、[期間二]からは[窓口二]宛てということで承知しました。"},{"id":"biz-062","category":"handover","title":"미완료 사항 인계","level":3,"setting":"휴가 전 동료에게 진행 중인 일을 넘긴다.","dialogue":[{"speaker":"상대","voice":"female","text":"資料は送付済みですが、先方の承認はまだです。返事が来たら、内容を確認して、関係者に共有をお願いします。"}],"meaning":"자료는 보냈지만 승인은 미완료이며 답변을 받으면 확인 후 공유해야 한다.","wrongMeanings":["자료 발송과 승인 모두 완료됐다.","답변을 받기 전에 승인 완료로 공유해야 한다.","답변은 확인 없이 삭제해야 한다."],"goal":"남은 일을 정확히 인수받으려면?","reply":"送付は完了、承認待ちですね。返事を確認してから、関係者に共有します。","wrongReplies":[{"text":"承認済みとして、今すぐ関係者に連絡します。","why":"승인 대기 상태를 완료로 바꾼다."},{"text":"資料は未送付なので、一から作り直します。","why":"이미 발송했다는 정보를 놓친다."},{"text":"返信は確認せずに削除します。","why":"인계받은 후속 업무와 반대다."}],"explanation":"인계에서는 완료한 일과 남은 일, 후속 행동을 구분해 복창한다.","formal":"送付済みで承認待ちとのこと、承知しました。ご返信の内容を確認後、関係者へ共有いたします。","internal":"送付済みで承認待ちですね。返事を見てから共有します。","pattern":"[完了事項]は完了、[未完了事項]は対応待ちですね。[次の行動]を進めます。"},{"id":"biz-063","category":"handover","title":"상의와 승인 구분","level":4,"setting":"본인 판단으로 외부에 확정 연락하면 안 되는 업무를 맡았다.","dialogue":[{"speaker":"상대","voice":"female","text":"先方との日程調整は進めて構いませんが、正式に決定する前に、必ず私に相談してください。"}],"meaning":"일정 조율은 진행해도 되지만 최종 결정 전에는 상의해야 한다.","wrongMeanings":["일정은 상의 없이 최종 확정해도 된다.","상대와 연락하는 것 자체가 금지됐다.","결정 후에만 보고하면 된다."],"goal":"조율은 하되 확정 전 상의하겠다고 답하려면?","reply":"候補日を調整し、正式に確定する前にご相談します。","wrongReplies":[{"text":"先方と確定した後で、ご報告します。","why":"상의해야 할 순서가 뒤바뀐다."},{"text":"先方には一切連絡しないことにします。","why":"허용된 조율까지 중단한다."},{"text":"相談せず、私の判断で決定します。","why":"사전 상의 조건을 무시한다."}],"explanation":"「進めて構わない」의 범위는 조율까지다. 최종 결정에는 별도의 상의 조건이 있다.","formal":"日程候補の調整まで進め、確定に先立って必ずご相談いたします。","internal":"候補日は調整し、決める前に相談します。","pattern":"[進めてよい作業]を進め、[確定する前]にご相談します。"},{"id":"biz-064","category":"handover","title":"역할과 책임자 재확인","level":5,"setting":"여러 부서가 공동 자료를 만든다.","dialogue":[{"speaker":"나","voice":"male","text":"資料作成の担当と、確認の流れを教えてください。"},{"speaker":"상대","voice":"female","text":"数値の入力は営業部、集計は企画部が担当します。最終確認は私が行いますので、各部から直接先方に送らないようお願いします。"}],"meaning":"영업부 입력, 기획부 집계, 발화자 최종 확인 후 외부 발송 절차를 따른다.","wrongMeanings":["각 부서가 최종 확인 없이 바로 외부에 보내도 된다.","기획부가 입력하고 영업부가 집계한다.","발화자는 최종 확인에 관여하지 않는다."],"goal":"기획부 담당자로서 자신의 범위를 확인하려면?","reply":"企画部で集計を行い、最終確認をお願いしてから送付する流れで承知しました。","wrongReplies":[{"text":"営業部で集計し、企画部で入力するということですね。","why":"역할을 뒤바꾼다."},{"text":"企画部で集計したら、確認を待たず直接送付します。","why":"최종 확인 전 직접 발송을 금지한 조건을 어긴다."},{"text":"最終確認は各部で独自に完了した扱いにします。","why":"지정된 최종 확인자를 임의로 바꾼다."}],"explanation":"역할 분담과 외부 발송 승인 흐름을 함께 이해해야 한다.","formal":"企画部にて集計後、最終確認に回付し、ご確認後に送付する手順で進めます。","internal":"企画部で集計して、最終確認を受けてから送る流れですね。","pattern":"[自分の担当作業]を行い、[確認者]の最終確認後に[次の作業]を進めます。"},{"id":"biz-065","category":"interview","title":"질문의 초점 확인","level":2,"setting":"면접관이 경험 소개를 부탁한다.","dialogue":[{"speaker":"상대","voice":"female","text":"その活動で、チーム全体の取り組みではなく、あなたご自身が担当したことを教えてください。"}],"meaning":"팀 전체 활동이 아니라 지원자 본인이 담당한 일을 묻는다.","wrongMeanings":["팀원 전원의 개인 정보를 묻는다.","활동의 사회적 배경만 설명해 달라는 뜻이다.","지원자의 담당은 말하지 말라는 뜻이다."],"goal":"본인의 담당부터 구체적으로 말하겠다고 응답하려면?","reply":"はい。私が担当した内容を、具体的にご説明いたします。","wrongReplies":[{"text":"チーム全体の成果だけをご説明します。","why":"본인 담당에 초점을 맞추라는 질문과 다르다."},{"text":"私自身の役割については一切触れません。","why":"질문한 정보를 의도적으로 제외한다."},{"text":"活動は他の方が担当したと仮定してお話しします。","why":"본인 경험을 설명하지 않는다."}],"explanation":"「ではなく」「ご自身」가 질문의 초점을 제한한다. 본인 기여와 전체 성과를 섞지 않는다.","formal":"承知いたしました。私自身が担った役割と、実際に行った行動を中心にお話しします。","internal":"はい。自分が担当したことから説明します。","pattern":"私が担当した[役割／行動]を、具体的にご説明します。"},{"id":"biz-066","category":"interview","title":"구체적 사례를 더 설명","level":3,"setting":"면접관이 추상적인 장점 설명을 구체화해 달라고 한다.","dialogue":[{"speaker":"상대","voice":"female","text":"調整力があるとのことですが、それが発揮された場面を、一つ挙げていただけますか。"}],"meaning":"조정 능력이 발휘된 구체적인 장면 하나를 요청한다.","wrongMeanings":["조정 능력이라는 표현의 사전 정의만 묻는다.","장점이 없다고 단정하고 있다.","여러 다른 사람의 경험을 대신 소개해 달라고 한다."],"goal":"실제 사례 하나를 설명하겠다고 시작하려면?","reply":"はい。意見が分かれた際に、役割を整理した経験についてお話しします。","wrongReplies":[{"text":"調整力という言葉の意味だけをご説明します。","why":"구체적인 장면을 요청했는데 정의만 설명한다."},{"text":"他の人が経験したことを、自分の経験としてお話しします。","why":"본인의 실제 경험에 근거하지 않는다."},{"text":"具体例は不要とのことで、説明を省きます。","why":"사례 요청을 반대로 이해한다."}],"explanation":"「場面を一つ」는 장점의 반복이 아닌 사례 제시를 요구한다.","formal":"一例として、意見の異なるメンバー間で役割を整理した際の経験をご説明いたします。","internal":"はい。意見が分かれたときに、役割を調整した経験があります。","pattern":"一例として、[状況]で[自分の行動]を行った経験をお話しします。"},{"id":"biz-067","category":"interview","title":"불명확한 조건을 면접에서 확인","level":4,"setting":"면접관이 초기 배치와 장기 이동 가능성을 설명한다.","dialogue":[{"speaker":"상대","voice":"female","text":"初任地は大阪を予定していますが、将来的には他拠点への異動の可能性もございます。"}],"meaning":"초기 근무지는 오사카 예정이지만 장기적으로 다른 거점 이동 가능성이 있다.","wrongMeanings":["오사카 평생 근무를 보장한다.","입사 직후 반드시 해외로 간다.","초기 배치가 도쿄로 확정됐다."],"goal":"이동 범위와 결정 방식에 관해 추가로 묻고 싶다면?","reply":"差し支えなければ、異動の対象となる地域と、決定の流れについて教えていただけますか。","wrongReplies":[{"text":"大阪での永続的な勤務が保証されるということですね。","why":"이동 가능성을 무시한다."},{"text":"初日から海外勤務が確定したと理解しました。","why":"가능성을 즉시 확정으로 확대한다."},{"text":"勤務地の説明は不要ですので、聞いていません。","why":"추가 정보 확인이라는 목적과 다르다."}],"explanation":"「予定」「可能性」는 확약이 아니다. 추가 질문은 필요한 항목을 구체화해 묻는다.","formal":"差し支えない範囲で、将来的な異動の範囲と判断の過程をお聞かせいただけますでしょうか。","internal":"差し支えなければ、異動先の地域や決まり方を教えてください。","pattern":"差し支えなければ、[確認したい範囲]と[決定の流れ]について教えていただけますか。"},{"id":"biz-068","category":"interview","title":"답변 길이 조절","level":5,"setting":"면접관이 결론을 먼저, 이후 배경을 듣고 싶다고 한다.","dialogue":[{"speaker":"나","voice":"male","text":"志望する仕事について、どのような順序でお話しすればよろしいですか。"},{"speaker":"상대","voice":"female","text":"まず結論を一言でお伝えいただいて、その後で、そう考えるようになった背景を簡潔にお話しください。"}],"meaning":"한 문장 결론을 먼저 말하고 그 뒤에 배경을 짧게 설명하라는 요청이다.","wrongMeanings":["처음부터 모든 연도와 사건을 길게 나열해 달라는 요청이다.","결론 없이 배경만 말해 달라는 요청이다.","추가 설명은 전혀 하지 말라는 뜻이다."],"goal":"요청한 순서에 맞춰 답변을 시작하려면?","reply":"結論から申しますと、部門間の連携に携わりたいと考えております。その背景をご説明いたします。","wrongReplies":[{"text":"まず、幼少期からの出来事をすべて順番にご説明します。","why":"결론 우선·간결함이라는 요청과 맞지 않는다."},{"text":"結論は申し上げず、背景だけを詳しくお話しします。","why":"결론을 먼저 말하라는 요청과 반대다."},{"text":"結論のみで、背景の説明は省きます。","why":"이후 배경도 설명하라는 요청을 충족하지 않는다."}],"explanation":"답변의 내용뿐 아니라 순서와 길이에 대한 지시를 듣는 문제다.","formal":"結論としては、部門をつなぐ業務に携わりたいと考えております。理由を簡潔にご説明申し上げます。","internal":"結論は、部門間をつなぐ仕事がしたいということです。その理由を説明します。","pattern":"結論から申しますと、[結論]です。その背景を簡潔にご説明します。"},{"id":"biz-069","category":"hotel","title":"예약자명 확인","level":2,"setting":"호텔 프런트에서 체크인 고객을 맞는다.","dialogue":[{"speaker":"상대","voice":"female","text":"チェックインをお願いしたいのですが、予約した者はまだ到着していません。同じ部屋に泊まる予定です。"}],"meaning":"예약한 사람은 아직 오지 않았고 같은 객실 투숙자가 먼저 체크인하려 한다.","wrongMeanings":["예약한 사람과 다른 객실로 변경해 달라는 요청이다.","예약을 취소하러 왔다.","예약 없이 객실을 새로 요청한다."],"goal":"예약 내용을 먼저 확인하려면?","reply":"ご予約内容を確認いたしますので、ご予約のお名前をお伺いしてもよろしいでしょうか。","wrongReplies":[{"text":"予約内容は確認せず、別の客室の鍵をお渡しします。","why":"예약 확인 없이 다른 객실 키를 주려 한다."},{"text":"キャンセルの手続きを進めます。","why":"취소를 요청하지 않았다."},{"text":"ご予約者様はすでにご到着済みですね。","why":"예약자가 미도착이라는 정보를 놓친다."}],"explanation":"확인에 필요한 정보부터 정중하게 요청한다. 체크인 가능 여부를 확인 전에 단정하지 않는다.","formal":"ご予約の確認をさせていただきます。恐れ入りますが、ご予約者様のお名前をお聞かせいただけますでしょうか。","internal":"予約を確認しますので、予約した方のお名前を教えていただけますか。","pattern":"[内容]を確認いたしますので、[必要な情報]をお伺いしてもよろしいでしょうか。"},{"id":"biz-070","category":"hotel","title":"가능 여부 확인 뒤 짐 보관 제안","level":3,"setting":"체크인 시각 전 도착한 고객이 객실 이용을 원한다.","dialogue":[{"speaker":"상대","voice":"female","text":"少し早く着いてしまったのですが、もう部屋に入れますか。無理であれば、荷物だけ預けたいです。"}],"meaning":"이른 입실이 가능한지 묻고 불가능하면 짐만 맡기고 싶어 한다.","wrongMeanings":["객실 이용을 완전히 취소한다.","짐 보관만 가능해도 반드시 거절하겠다는 뜻이다.","체크아웃을 늦추고 싶다는 요청이다."],"goal":"객실 상태를 확인하고 짐 보관은 가능하다고 안내하려면?","reply":"客室の準備状況を確認いたします。お荷物は先にお預かりできます。","wrongReplies":[{"text":"お部屋の確認はせず、準備済みとお約束します。","why":"확인 전 입실 가능 상태를 보장한다."},{"text":"チェックアウトの延長をご希望ですね。","why":"요청 방향이 다르다."},{"text":"お荷物だけでも預けたくないということですね。","why":"고객이 제시한 대안을 반대로 이해한다."}],"explanation":"우선 요청과 대체 요청을 함께 이해한다. 확인할 사항과 바로 가능한 서비스를 구분한다.","formal":"客室のご用意を確認してまいります。お荷物につきましては、先にお預かりいたします。","internal":"部屋の準備を確認します。荷物は先にお預かりできます。","pattern":"[確認が必要な事項]を確認いたします。[先に提供できる対応]は可能です。"},{"id":"biz-071","category":"hotel","title":"방 소음 불편에 대응","level":4,"setting":"호텔 고객이 객실 소음 때문에 불편을 겪었다.","dialogue":[{"speaker":"상대","voice":"female","text":"隣の部屋の音が気になって、なかなか眠れません。可能であれば、静かな部屋に替えていただけませんか。"}],"meaning":"인접 객실 소음 때문에 가능하면 조용한 방으로 바꾸고 싶어 한다.","wrongMeanings":["객실 요금을 즉시 올려 달라는 요청이다.","고객이 소음을 내겠다고 알린다.","예약 날짜만 바꾸고 싶다는 요청이다."],"goal":"불편에 사과하고 이동 가능한 객실을 확인하려면?","reply":"ご不便をおかけし申し訳ございません。ご移動いただける静かなお部屋があるか、確認いたします。","wrongReplies":[{"text":"空室を確認せず、必ず今すぐ移動できるとお約束します。","why":"확인되지 않은 객실 이동을 보장한다."},{"text":"ご宿泊日を来月に変更するということですね。","why":"현재의 소음 문제와 요청이 다르다."},{"text":"音は気にせず、そのままお待ちください。","why":"불편과 객실 변경 요청에 대응하지 않는다."}],"explanation":"공감과 사과 후 가능한 해결책을 확인한다. 객실 상태를 알기 전에 교체를 확약하지 않는다.","formal":"ご迷惑をおかけし、誠に申し訳ございません。静かなお部屋へのご案内が可能か、ただいま確認いたします。","internal":"申し訳ありません。静かな部屋に移れるか、確認します。","pattern":"ご不便をおかけし申し訳ございません。[希望の対応]が可能か確認いたします。"},{"id":"biz-072","category":"hotel","title":"환불 결정권 없는 접수 대응","level":5,"setting":"고객이 서비스 불만으로 환불 여부를 묻는다.","dialogue":[{"speaker":"나","voice":"male","text":"昨日の件について、どのような対応をご希望でしょうか。"},{"speaker":"상대","voice":"female","text":"昨日の対応について納得していません。返金していただけるか、責任者の方に確認してもらえますか。"}],"meaning":"고객은 전날 응대에 불만이 있어 책임자에게 환불 가능 여부 확인을 요청한다.","wrongMeanings":["접수 직원에게 규정과 관계없이 즉시 환불을 확정하라고 했다.","불만 내용을 더는 말하지 않겠다는 뜻이다.","객실 청소 시간만 문의한다."],"goal":"접수 담당자로서 확인을 맡겠다고 답하려면?","reply":"昨日の対応につきまして申し訳ございません。責任者に状況を確認し、ご案内いたします。","wrongReplies":[{"text":"私の判断だけで、すべて返金済みとして処理します。","why":"권한과 확인을 건너뛰고 완료를 말한다."},{"text":"責任者への確認はせず、返金は絶対にできないと断定します。","why":"요청한 확인을 하지 않고 결론을 단정한다."},{"text":"お部屋の清掃時間だけをご案内します。","why":"불만과 환불 문의에 답하지 않는다."}],"explanation":"접수·확인·결정의 역할을 구분한다. 확인 전 환불 여부를 임의로 단정하지 않는다.","formal":"ご不快な思いをおかけし、申し訳ございません。責任者に確認のうえ、対応についてご案内申し上げます。","internal":"申し訳ありません。責任者に確認してからご案内します。","pattern":"[お詫び]。[判断する担当者]に確認のうえ、対応をご案内します。"},{"id":"biz-073","category":"relations","title":"배려를 받아들이며 감사","level":2,"setting":"상대가 업무 부담을 줄이도록 기한을 배려한다.","dialogue":[{"speaker":"상대","voice":"female","text":"お忙しいと思いますので、今日中でなくても大丈夫です。明日の午前中までにいただければ助かります。"}],"meaning":"오늘이 아니어도 되고 내일 오전까지 받으면 된다는 배려다.","wrongMeanings":["오늘 자정까지 반드시 제출해야 한다.","제출 자체가 필요 없어졌다.","내일 오후 늦게 보내라는 요청이다."],"goal":"배려에 감사하고 새 기한을 확인하려면?","reply":"ご配慮ありがとうございます。それでは、明日の午前中までにお送りします。","wrongReplies":[{"text":"本日中が絶対条件とのことで承知しました。","why":"완화된 기한을 반대로 이해한다."},{"text":"提出は不要とのことですので、作業を中止します。","why":"기한 배려를 제출 취소로 바꾼다."},{"text":"明日の夜にお送りすることで確定します。","why":"내일 오전이라는 기한을 넘긴다."}],"explanation":"감사 표현 후 완화된 기한을 다시 말하면 서로의 기대가 맞아진다.","formal":"ご配慮いただき、誠にありがとうございます。明日午前中までにお届けいたします。","internal":"お気遣いありがとうございます。明日の午前中までに送ります。","pattern":"ご配慮ありがとうございます。それでは、[合意した期限]までにお送りします。"},{"id":"biz-074","category":"relations","title":"부담을 줄이는 도움 제안","level":3,"setting":"동료가 일이 많아 점심시간에도 작업 중이다.","dialogue":[{"speaker":"상대","voice":"female","text":"今日中に確認する資料が重なっていて、少し立て込んでいます。"}],"meaning":"오늘 확인할 자료가 겹쳐 바쁘다는 뜻이다.","wrongMeanings":["오늘 확인할 일이 전혀 없다.","모든 확인이 완료돼 한가하다.","동료에게 즉시 사직하라는 뜻이다."],"goal":"업무 일부를 나눠 도와주고 싶다면?","reply":"私で対応できることがあれば、お手伝いしましょうか。","wrongReplies":[{"text":"確認する資料がないので、作業は不要ですね。","why":"현재 업무량을 반대로 이해한다."},{"text":"ご本人に確認せず、すべて完了済みと報告します。","why":"도움이 아니라 허위 완료 보고다."},{"text":"こちらの資料も、追加で全部お願いしておきます。","why":"부담을 줄이려는 목적과 반대다."}],"explanation":"「立て込んでいる」는 일이 몰려 바쁜 상태다. 도움을 제안하되 임의로 업무를 빼앗거나 완료 처리하지 않는다.","formal":"もし私でお力になれることがございましたら、一部お引き受けできればと思います。","internal":"私にできることがあれば、手伝いましょうか。","pattern":"私で[対応できること]があれば、お手伝いしましょうか。"},{"id":"biz-075","category":"relations","title":"격려와 수정 요청 구분","level":4,"setting":"상사가 초안을 칭찬한 뒤 핵심 수정을 부탁한다.","dialogue":[{"speaker":"상대","voice":"female","text":"全体の流れはよく整理されていますね。結論だけ、もう少し具体的にしてもらえると、さらに伝わりやすくなると思います。"}],"meaning":"전체 흐름은 좋으며 결론을 더 구체화하면 좋겠다는 뜻이다.","wrongMeanings":["전체를 처음부터 폐기하라는 지시다.","수정할 부분이 전혀 없다는 확정이다.","결론을 삭제하라는 요청이다."],"goal":"좋은 흐름은 유지하고 결론만 보완하려면?","reply":"ありがとうございます。全体の流れはそのままにして、結論をより具体的に修正します。","wrongReplies":[{"text":"修正は不要とのことですので、そのまま提出します。","why":"구체적인 보완 요청을 놓친다."},{"text":"結論はすべて削除いたします。","why":"구체화 요청과 반대다."},{"text":"全体の流れを廃棄して、一からやり直します。","why":"좋다고 평가한 부분까지 불필요하게 바꾼다."}],"explanation":"긍정 평가 뒤에 담긴 구체적 요청을 듣는다. 칭찬을 수정 불필요로 이해하지 않는다.","formal":"ご助言ありがとうございます。構成を維持しつつ、結論部分の具体性を高める形で修正いたします。","internal":"ありがとうございます。流れは残して、結論を具体的に直します。","pattern":"[良い点]はそのままにして、[修正対象]をより[望ましい状態]に修正します。"},{"id":"biz-076","category":"relations","title":"도움을 준 상대에게 구체적으로 감사","level":5,"setting":"타 부서가 바쁜 가운데 검토를 도와 기한을 맞췄다.","dialogue":[{"speaker":"나","voice":"male","text":"今回は、確認にご協力いただきありがとうございました。"},{"speaker":"상대","voice":"female","text":"確認が間に合ってよかったです。今後も、早めに共有いただければ、可能な範囲で協力します。"}],"meaning":"이번 확인이 기한에 맞았고 앞으로도 일찍 공유하면 가능한 범위에서 협조하겠다는 뜻이다.","wrongMeanings":["앞으로 모든 요청을 무조건 즉시 처리하겠다고 보장했다.","앞으로는 어떤 협조도 하지 않겠다고 했다.","이번 확인이 기한을 넘겼다고 알렸다."],"goal":"감사와 함께 다음에는 일찍 공유하겠다고 답하려면?","reply":"お忙しい中ご確認いただき、ありがとうございました。次回は余裕を持って共有いたします。","wrongReplies":[{"text":"今後はすべて即時対応を保証いただいたと理解しました。","why":"조건부 협조를 무조건 보장으로 확대한다."},{"text":"今後は早めの共有を控えるようにします。","why":"협조 조건과 반대다."},{"text":"今回は確認が間に合わなかったと報告します。","why":"성공적으로 기한을 맞춘 사실과 다르다."}],"explanation":"감사의 대상 행동을 구체적으로 말하고 상대가 제시한 향후 협조 조건도 반영한다.","formal":"ご多忙のところお力添えいただき、誠にありがとうございました。今後は余裕をもって情報共有いたします。","internal":"忙しい中ありがとうございました。次はもっと早めに共有します。","pattern":"[相手の状況]にもかかわらず[協力内容]いただき、ありがとうございました。次回は[改善点]いたします。"},{"id":"biz-077","category":"global","title":"현지 시각과 일본 시각 구분","level":2,"setting":"해외 담당자가 회의 시각을 안내한다.","dialogue":[{"speaker":"상대","voice":"female","text":"会議は現地時間の午前九時、日本時間では午後五時の開始となります。"}],"meaning":"현지 9시는 일본 17시에 해당하며 그 시각에 회의가 시작된다.","wrongMeanings":["일본 시각 9시에 시작한다.","일본 시각 오전 5시에 시작한다.","현지 17시에 끝난다는 안내다."],"goal":"일본에서 접속할 시각을 확인하려면?","reply":"日本時間の十七時に接続する、ということで承知しました。","wrongReplies":[{"text":"日本時間の午前九時に接続します。","why":"현지 시각을 일본 시각으로 잘못 적용한다."},{"text":"日本時間の午前五時に接続します。","why":"오후 5시를 오전으로 바꾼다."},{"text":"開始時刻は未定ということですね。","why":"이미 안내한 시작 시각을 미정으로 이해한다."}],"explanation":"시차 문제에서는 숫자뿐 아니라 어느 지역 기준인지 듣는다.","formal":"日本時間の十七時開始とのこと、承知いたしました。そちらの時刻に合わせて参加いたします。","internal":"日本時間で夕方五時ですね。その時間につなぎます。","pattern":"[基準となる地域]時間の[時刻]に接続するということで承知しました。"},{"id":"biz-078","category":"global","title":"현지 의견과 본사 승인 연결","level":3,"setting":"해외 법인은 제안에 찬성하지만 본사 검토가 남았다.","dialogue":[{"speaker":"상대","voice":"female","text":"現地では問題ないと考えていますが、本社の承認が必要です。こちらで承認依頼を上げておきます。"}],"meaning":"현지 판단은 긍정적이지만 본사 승인이 아직 필요하다.","wrongMeanings":["본사 승인까지 이미 끝났다.","현지가 제안을 완전히 거절했다.","본사에 확인할 필요가 없다."],"goal":"승인 결과를 받은 뒤 진행하겠다고 답하려면?","reply":"ありがとうございます。本社の承認結果をいただいてから、次の手続きを進めます。","wrongReplies":[{"text":"本社の承認済みとして、本日から実行します。","why":"승인 요청과 승인 완료를 혼동한다."},{"text":"現地で反対とのことで、提案を撤回します。","why":"현지의 긍정적 판단을 반대로 이해한다."},{"text":"本社への承認依頼は取り下げてください。","why":"필요한 승인 절차를 중단한다."}],"explanation":"「問題ないと考える」는 현지 의견이고 「承認が必要」는 남은 절차다.","formal":"承認のお手続きをお願いいたします。結果を確認後、次の段階へ進めさせていただきます。","internal":"ありがとうございます。本社の承認が出てから次に進めます。","pattern":"[承認者]の承認結果をいただいてから、[次の手続き]を進めます。"},{"id":"biz-079","category":"global","title":"번역보다 조건의 의미 확인","level":4,"setting":"해외 팀과 가격 조건의 해석을 맞춘다.","dialogue":[{"speaker":"상대","voice":"female","text":"資料の翻訳は終わりましたが、支払い条件の解釈に違いがあるようです。文言だけでなく、運用も確認したいと思います。"}],"meaning":"번역은 끝났지만 지급 조건 해석 차이가 있어 실제 운영까지 확인하려 한다.","wrongMeanings":["번역이 끝나 모든 조건의 합의도 끝났다.","지급 조건 검토가 취소됐다.","번역을 다시 할 필요가 없다는 이유로 운영 확인도 하지 않기로 했다."],"goal":"조항 의미와 실제 처리 흐름을 함께 확인하자고 답하려면?","reply":"支払い条件の意味と、実際の処理の流れを、双方で確認しましょう。","wrongReplies":[{"text":"翻訳済みですので、条件の確認は一切不要です。","why":"번역 완료를 해석 일치로 오해한다."},{"text":"支払い条件は合意済みとして変更できません。","why":"아직 해석 차이가 있는 상태를 합의로 확정한다."},{"text":"資料の表紙だけを確認して終えましょう。","why":"확인할 핵심을 다루지 않는다."}],"explanation":"번역 완료와 업무 조건 합의는 다르다. 단어가 같아도 실제 절차를 함께 확인해야 한다는 상황이다.","formal":"文言の解釈と実務上の処理について、双方の認識をすり合わせる機会を設けましょう。","internal":"支払い条件の意味と実際のやり方を、両方で確認しましょう。","pattern":"[文言の意味]と[実際の運用]を、双方で確認しましょう。"},{"id":"biz-080","category":"global","title":"현지 영업일과 본사 마감 조정","level":5,"setting":"본사 마감과 해외 휴일이 겹쳐 전체 확인이 어렵다.","dialogue":[{"speaker":"나","voice":"male","text":"本社の締め切りに向けて、どのように進められそうですか。"},{"speaker":"상대","voice":"female","text":"本社の締め切りは金曜日ですが、現地は木曜と金曜が休業日です。水曜日までに確認できた分を先に送り、残りは翌週月曜に補足してもよろしいでしょうか。"}],"meaning":"수요일까지 확인한 부분을 먼저 보내고 휴무 뒤 월요일에 나머지를 보완하겠다는 제안이다.","wrongMeanings":["모든 자료를 금요일 현지에서 확인해 한 번에 보내겠다는 뜻이다.","수요일에 모든 검토가 끝난다고 보장한다.","본사 마감을 확인 없이 없애겠다는 통보다."],"goal":"본사에 부분 선제출·월요일 보완 가능 여부를 확인하겠다고 답하려면?","reply":"水曜日までの確認分を先に提出し、残りを月曜に補足する形でよいか、本社に確認します。","wrongReplies":[{"text":"すべて金曜に確認済みとして、本社に報告します。","why":"현지 휴무와 미확정 부분을 반영하지 않는다."},{"text":"水曜までに全件完了を保証いただいたと伝えます。","why":"확인된 부분만 보내겠다는 제안을 전체 완료 보장으로 바꾼다."},{"text":"本社への確認はせず、締め切りを独自に廃止します。","why":"마감 변경에 필요한 조율을 생략한다."}],"explanation":"선제출 범위·현지 휴무·본사 마감·후속 보완 시점을 구분해 전달한다.","formal":"水曜までの確認分を先行提出し、未確認分を翌週月曜に追補する進め方について、本社と調整いたします。","internal":"水曜までの分を先に出し、残りは月曜に補足できるか本社に聞きます。","pattern":"[確認済みの範囲]を先に提出し、残りを[時期]に補足する形でよいか、[承認先]に確認します。"}];

export const CATEGORIES=[...BASE_CATEGORIES,...KEIGO_CATEGORIES];
export const SCENES=[...BASE_SCENES,...KEIGO_SCENES];
